import { describe, it, expect, jest } from '@jest/globals';
import * as THREE from 'three';
import { stepEnemy, TUNING } from '../../../src/actors/EnemyAI.js';

const MARK = { tag: 'mark-colour' };

function ground(y = 0, extra = {}) {
  return { y, islandId: 1, u: 0.1, slope: 0, ...extra };
}

/** Every mutable field stepEnemy reads, with production-shaped defaults. */
function makeEnemy(opts = {}) {
  const e = {
    kind: opts.kind || 'gnorc',
    tune: null,
    meta: null,
    group: { visible: true },
    position: new THREE.Vector3(0, 0, 0),
    home: new THREE.Vector3(0, 0, 0),
    target: new THREE.Vector3(0, 0, 0),
    knock: new THREE.Vector3(0, 0, 0),
    alive: true,
    state: 'patrol',
    stateTime: 0,
    deadTime: 0,
    cooldown: 0,
    struck: false,
    diveTime: 0,
    locomotion: 0,
    yaw: 0,
    phase: 0,
    groundY: 0,
    rnd_speed: 1,
    wanderTime: 5,
    homeIsland: 1,
    markColor: MARK,
    despawned: false,
    ...opts,
    tune: { ...TUNING[opts.kind || 'gnorc'], ...(opts.tune || {}) },
    meta: { height: 1.5, groundOffset: 0, ...(opts.meta || {}) },
    group: { visible: true, ...(opts.group || {}) },
    rnd: opts.rnd || { range: jest.fn((min, max) => min + 0.5 * (max - min)) },
    onState: opts.onState || jest.fn(),
  };
  return e;
}

function makeCtx({ player = new THREE.Vector3(0, 0, 0), sampleGround, ...rest } = {}) {
  return {
    player: { position: player },
    world: { sampleGround: sampleGround || jest.fn(() => ground()) },
    engine: { camera: { quaternion: new THREE.Quaternion() } },
    controller: { hurt: jest.fn() },
    projectiles: { fire: jest.fn() },
    enemyFx: { pushMark: jest.fn() },
    time: 0,
    ...rest,
  };
}

const states = (e) => e.onState.mock.calls.map((c) => c[0]);

describe('stepEnemy — dead enemies', () => {
  it('advances deadTime, sinks toward the ground and hides/despawns after 1.1s', () => {
    const e = makeEnemy({ alive: false, deadTime: 1.0, position: new THREE.Vector3(4, 5, 2), groundY: 0, cooldown: 0.5 });
    const ctx = makeCtx();

    stepEnemy(e, 0.09, ctx);

    expect(e.deadTime).toBeCloseTo(1.09, 10);
    expect(e.position.y).toBeGreaterThan(0);
    expect(e.position.y).toBeLessThan(5);
    expect(e.group.visible).toBe(true);
    expect(e.despawned).toBe(false);
    expect(e.position.x).toBe(4);
    expect(e.position.z).toBe(2);
    // Dead enemies return before the shared cooldown tick or ground query.
    expect(e.cooldown).toBe(0.5);
    expect(ctx.world.sampleGround).not.toHaveBeenCalled();

    stepEnemy(e, 0.02, ctx);

    expect(e.deadTime).toBeCloseTo(1.11, 10);
    expect(e.group.visible).toBe(false);
    expect(e.despawned).toBe(true);
  });

  it('does not set despawned when the group was already hidden', () => {
    const e = makeEnemy({ alive: false, deadTime: 2, group: { visible: false } });
    stepEnemy(e, 0.1, makeCtx());
    expect(e.group.visible).toBe(false);
    expect(e.despawned).toBe(false);
  });

  it('sinks flying corpses more slowly than grounded ones', () => {
    const walker = makeEnemy({ alive: false, position: new THREE.Vector3(0, 10, 0) });
    const flyer = makeEnemy({ alive: false, kind: 'flyer', position: new THREE.Vector3(0, 10, 0) });
    const ctx = makeCtx();

    stepEnemy(walker, 0.1, ctx);
    stepEnemy(flyer, 0.1, ctx);

    expect(walker.position.y).toBeLessThan(flyer.position.y);
    expect(flyer.position.y).toBeLessThan(10);
  });
});

describe('stepEnemy — hurt', () => {
  it('rides out knockback, decays it, and returns before cooldown ticks', () => {
    const e = makeEnemy({ state: 'hurt', stateTime: 0.1, knock: new THREE.Vector3(3, 0, 0), cooldown: 0.5 });
    const ctx = makeCtx();

    stepEnemy(e, 0.1, ctx);

    expect(e.state).toBe('hurt');
    expect(e.stateTime).toBeCloseTo(0.2, 10);
    expect(e.position.x).toBeCloseTo(0.3, 10);
    expect(e.knock.x).toBeGreaterThan(1);
    expect(e.knock.x).toBeLessThan(2);
    expect(e.cooldown).toBe(0.5);
    expect(states(e)).toEqual([]);
  });

  it('does not move for negligible knockback', () => {
    const e = makeEnemy({ state: 'hurt', knock: new THREE.Vector3(0.05, 0, 0) });
    const ctx = makeCtx();
    stepEnemy(e, 0.1, ctx);
    expect(e.position.x).toBe(0);
    expect(e.knock.x).toBe(0.05);
    expect(ctx.world.sampleGround).not.toHaveBeenCalled();
  });

  it('refuses knocked-back movement onto invalid ground but still decays the knock', () => {
    const e = makeEnemy({ state: 'hurt', knock: new THREE.Vector3(3, 0, 0) });
    const ctx = makeCtx({ sampleGround: jest.fn(() => null) });
    stepEnemy(e, 0.1, ctx);
    expect(e.position.x).toBe(0);
    expect(e.knock.x).toBeGreaterThan(1);
    expect(e.knock.x).toBeLessThan(3);
  });

  it('returns to hurt until strictly after 0.45s, then chases a visible player', () => {
    const e = makeEnemy({ state: 'hurt', stateTime: 0.45 });
    const ctx = makeCtx({ player: new THREE.Vector3(5, 0, 0) });

    stepEnemy(e, 0, ctx);
    expect(e.state).toBe('hurt');

    stepEnemy(e, 0.01, ctx);
    expect(e.state).toBe('chase');
    expect(e.stateTime).toBe(0);
    expect(states(e)).toEqual(['chase']);
  });

  it('returns to patrol when the player is out of sight', () => {
    const e = makeEnemy({ state: 'hurt', stateTime: 0.44, struck: true });
    const ctx = makeCtx({ player: new THREE.Vector3(30, 0, 0) });
    stepEnemy(e, 0.02, ctx);
    expect(e.state).toBe('patrol');
    expect(e.struck).toBe(false);
  });
});

describe('stepEnemy — patrol', () => {
  it('picks a wander target, faces it and walks there', () => {
    const e = makeEnemy({ wanderTime: 0 });
    const ctx = makeCtx({ player: new THREE.Vector3(30, 0, 0) });

    stepEnemy(e, 0.1, ctx);

    // rnd.range returns 0.5 for every call: angle π, radius 3.5.
    expect(e.rnd.range).toHaveBeenNthCalledWith(1, 1.6, 4.2);
    expect(e.rnd.range).toHaveBeenNthCalledWith(2, 0, Math.PI * 2);
    expect(e.rnd.range).toHaveBeenNthCalledWith(3, 0.35, 1);
    expect(e.wanderTime).toBeCloseTo(2.9, 10);
    expect(e.target.x).toBeCloseTo(-4.725, 10);
    expect(e.target.z).toBeCloseTo(0, 10);
    expect(e.position.x).toBeCloseTo(-0.31, 10);
    expect(e.position.z).toBeCloseTo(0, 10);
    expect(e.yaw).toBeCloseTo(-0.35 * (Math.PI / 2), 8);
    expect(e.locomotion).toBeGreaterThan(1);
    expect(e.locomotion).toBeLessThan(3.1);
    expect(e.state).toBe('patrol');
  });

  it('keeps walking toward an existing target without repicking', () => {
    const e = makeEnemy({ wanderTime: 5, target: new THREE.Vector3(10, 0, 0) });
    const ctx = makeCtx({ player: new THREE.Vector3(30, 0, 0) });
    stepEnemy(e, 0.1, ctx);
    expect(e.position.x).toBeCloseTo(0.31, 10);
    expect(e.wanderTime).toBeCloseTo(4.9, 10);
    expect(e.rnd.range).not.toHaveBeenCalled();
  });

  it('stops when the wander target is within 0.6 units', () => {
    const e = makeEnemy({ target: new THREE.Vector3(0.3, 0, 0), locomotion: 4 });
    stepEnemy(e, 0.1, makeCtx({ player: new THREE.Vector3(30, 0, 0) }));
    expect(e.position.x).toBe(0);
    expect(e.locomotion).toBeGreaterThan(0);
    expect(e.locomotion).toBeLessThan(4);
    expect(e.rnd.range).not.toHaveBeenCalled();
  });

  it('repicks immediately when the step is blocked by the world', () => {
    const e = makeEnemy({ wanderTime: 5, target: new THREE.Vector3(10, 0, 0) });
    const ctx = makeCtx({ sampleGround: jest.fn(() => null), player: new THREE.Vector3(30, 0, 0) });
    stepEnemy(e, 0.1, ctx);
    expect(e.position.x).toBe(0);
    expect(e.wanderTime).toBe(0);
    expect(ctx.world.sampleGround).toHaveBeenCalled();
  });

  it('never wanders or repicks when stationary', () => {
    const e = makeEnemy({ kind: 'turret', state: 'patrol', target: new THREE.Vector3(10, 0, 0) });
    stepEnemy(e, 0.1, makeCtx({ player: new THREE.Vector3(100, 0, 0) }));
    expect(e.position.x).toBe(0);
    expect(e.locomotion).toBe(0);
    expect(e.rnd.range).not.toHaveBeenCalled();
    expect(e.state).toBe('patrol');
  });

  it('alerts on a visible player even while stationary', () => {
    const e = makeEnemy({ kind: 'turret', state: 'patrol', stateTime: 7 });
    stepEnemy(e, 0.1, makeCtx({ player: new THREE.Vector3(5, 0, 0) }));
    expect(e.state).toBe('alert');
    expect(e.stateTime).toBe(0);
    expect(states(e)).toEqual(['alert']);
  });

  it('does not alert when the player is out of sight', () => {
    const e = makeEnemy();
    stepEnemy(e, 0.1, makeCtx({ player: new THREE.Vector3(18, 0, 0) }));
    expect(e.state).toBe('patrol');
    expect(states(e)).toEqual([]);
  });

  it('judges sight from horizontal distance only', () => {
    const e = makeEnemy({ kind: 'turret', state: 'patrol' });
    stepEnemy(e, 0.1, makeCtx({ player: new THREE.Vector3(5, 100, 0) }));
    expect(e.state).toBe('alert');
  });

  it('keeps a thief patrolling while the player is visible but outside flee range', () => {
    const e = makeEnemy({ kind: 'thief', target: new THREE.Vector3(0, 0, 0) });
    const ctx = makeCtx({ player: new THREE.Vector3(20, 0, 0) });

    stepEnemy(e, 0.1, ctx);
    expect(e.state).toBe('patrol');

    ctx.player.position.set(10, 0, 0);
    stepEnemy(e, 0.1, ctx);
    expect(e.state).toBe('alert');
  });
});

describe('stepEnemy — alert', () => {
  it('faces the player, stops, and posts a mark above its head every frame', () => {
    const e = makeEnemy({ state: 'alert', position: new THREE.Vector3(0, 0, 2), locomotion: 2, meta: { height: 2 } });
    const ctx = makeCtx({ player: new THREE.Vector3(10, 0, 2) });

    stepEnemy(e, 0.1, ctx);

    expect(e.stateTime).toBeCloseTo(0.1, 10);
    expect(e.yaw).toBeGreaterThan(0);
    expect(e.yaw).toBeLessThan(Math.PI / 2);
    expect(e.locomotion).toBeLessThan(2);
    expect(ctx.enemyFx.pushMark).toHaveBeenCalledTimes(1);

    const [pos, color, scale, camera] = ctx.enemyFx.pushMark.mock.calls[0];
    expect(pos.x).toBe(0);
    expect(pos.y).toBeCloseTo(2.3, 10); // position.y + height * 1.15
    expect(pos.z).toBe(2);
    expect(color).toBe(MARK);
    expect(scale).toBe(1);
    expect(camera).toBe(ctx.engine.camera);
    // The mark is a copy: the enemy itself does not float upward.
    expect(e.position.y).toBe(0);
  });

  it('stays alert at exactly 0.5s and promotes to chase afterwards', () => {
    const e = makeEnemy({ state: 'alert', stateTime: 0.5 });
    const ctx = makeCtx({ player: new THREE.Vector3(5, 0, 0) });

    stepEnemy(e, 0, ctx);
    expect(e.state).toBe('alert');

    stepEnemy(e, 0.01, ctx);
    expect(e.state).toBe('chase');
    expect(states(e)).toEqual(['chase']);
  });

  it('promotes a thief to flee', () => {
    const e = makeEnemy({ kind: 'thief', state: 'alert', stateTime: 0.5 });
    stepEnemy(e, 0.1, makeCtx({ player: new THREE.Vector3(5, 0, 0) }));
    expect(e.state).toBe('flee');
  });

  it('tolerates a missing enemy-fx service', () => {
    const e = makeEnemy({ state: 'alert' });
    const ctx = makeCtx({ player: new THREE.Vector3(5, 0, 0), enemyFx: null });
    expect(() => stepEnemy(e, 0.1, ctx)).not.toThrow();
  });
});

describe('stepEnemy — flee', () => {
  it('runs directly away from the player at chase speed', () => {
    const e = makeEnemy({ kind: 'thief', state: 'flee' });
    const ctx = makeCtx({ player: new THREE.Vector3(10, 0, 0) });

    stepEnemy(e, 0.1, ctx);

    expect(e.position.x).toBeCloseTo(-0.96, 10);
    expect(e.position.z).toBeCloseTo(0, 10);
    expect(e.locomotion).toBeGreaterThan(5);
    expect(e.state).toBe('flee');
  });

  it('curves back toward home once beyond 1.6 patrol radii', () => {
    const e = makeEnemy({ kind: 'thief', state: 'flee', position: new THREE.Vector3(30, 0, 0) });
    const ctx = makeCtx({ player: new THREE.Vector3(10, 0, 0) });

    stepEnemy(e, 0.1, ctx);

    expect(e.position.x).toBeLessThan(30);
    expect(e.position.x).toBeCloseTo(29.04, 10);
  });

  it('dodges sideways when the direct escape route is blocked', () => {
    const e = makeEnemy({ kind: 'thief', state: 'flee' });
    const sampleGround = jest.fn((x) => (x < 0 ? null : ground()));
    const ctx = makeCtx({ player: new THREE.Vector3(5, 0, 0), sampleGround });

    stepEnemy(e, 0.1, ctx);

    expect(e.position.x).toBeCloseTo(0, 10);
    expect(e.position.z).toBeCloseTo(-0.96, 10);
    expect(sampleGround).toHaveBeenCalledTimes(3); // failed direct, dodge, altitude
  });

  it('stays put when both escape directions are blocked', () => {
    const e = makeEnemy({ kind: 'thief', state: 'flee' });
    const ctx = makeCtx({ player: new THREE.Vector3(5, 0, 0), sampleGround: jest.fn(() => null) });
    stepEnemy(e, 0.1, ctx);
    expect(e.position.x).toBe(0);
    expect(e.position.z).toBe(0);
    expect(e.state).toBe('flee');
  });

  it('returns to patrol once the player is more than 1.4x sight away', () => {
    const e = makeEnemy({ kind: 'thief', state: 'flee', stateTime: 3 });
    const ctx = makeCtx({ player: new THREE.Vector3(31, 0, 0) });
    stepEnemy(e, 0.1, ctx);
    expect(e.state).toBe('patrol');
    expect(e.stateTime).toBe(0);
    expect(states(e)).toEqual(['patrol']);
  });
});

describe('stepEnemy — chase', () => {
  it('closes distance at chase speed and turns toward the player', () => {
    const e = makeEnemy({ state: 'chase' });
    const ctx = makeCtx({ player: new THREE.Vector3(10, 0, 0) });

    stepEnemy(e, 0.1, ctx);

    expect(e.position.x).toBeCloseTo(0.5, 10);
    expect(e.yaw).toBeCloseTo(0.7 * (Math.PI / 2), 10);
    expect(e.locomotion).toBeGreaterThan(1);
    expect(e.state).toBe('chase');
  });

  it('holds at the edge and slows when the step is blocked', () => {
    const e = makeEnemy({ state: 'chase', locomotion: 5 });
    const ctx = makeCtx({ player: new THREE.Vector3(10, 0, 0), sampleGround: jest.fn(() => null) });

    stepEnemy(e, 0.1, ctx);

    expect(e.position.x).toBe(0);
    expect(e.locomotion).toBeLessThan(5);
    expect(e.locomotion).toBeGreaterThan(0);
    expect(e.state).toBe('chase');
  });

  it('stops advancing inside 0.85 attack range while on cooldown', () => {
    const e = makeEnemy({ state: 'chase', cooldown: 1, locomotion: 4 });
    const ctx = makeCtx({ player: new THREE.Vector3(1.5, 0, 0) });

    stepEnemy(e, 0.1, ctx);

    expect(e.position.x).toBe(0);
    expect(e.state).toBe('chase');
    expect(e.cooldown).toBeCloseTo(0.9, 10);
