describe('stepEnemy — windup', () => {
  it('faces the player and settles locomotion while winding up', () => {
    const e = makeEnemy({ state: 'windup', yaw: Math.PI, locomotion: 5 });
    stepEnemy(e, 0.1, makeCtx({ player: new THREE.Vector3(0, 0, 10) }));
    expect(e.yaw).toBeLessThan(Math.PI);
    expect(e.yaw).toBeGreaterThan(0);
    expect(e.locomotion).toBeLessThan(5);
    expect(e.locomotion).toBeGreaterThan(0);
    expect(e.state).toBe('windup');
  });

  it('strikes once the windup duration is reached', () => {
    const e = makeEnemy({ state: 'windup', stateTime: 0.3, struck: true });
    const ctx = makeCtx({ player: new THREE.Vector3(0, 0, 10) });

    stepEnemy(e, 0.1, ctx);
    expect(e.state).toBe('windup');
    expect(e.stateTime).toBeCloseTo(0.4, 10);

    stepEnemy(e, 0.05, ctx);
    expect(e.state).toBe('strike');
    expect(e.stateTime).toBe(0);
    expect(e.struck).toBe(false);
    expect(states(e)).toEqual(['strike']);
  });
});

describe('stepEnemy — strike', () => {
  it('lands a melee hit exactly once when the player is in reach', () => {
    const e = makeEnemy({ state: 'strike' });
    const ctx = makeCtx({ player: new THREE.Vector3(1, 0, 0) });

    stepEnemy(e, 0.05, ctx);

    expect(e.struck).toBe(true);
    expect(e.state).toBe('strike');
    expect(e.stateTime).toBeCloseTo(0.05, 10);
    expect(ctx.controller.hurt).toHaveBeenCalledTimes(1);
    expect(ctx.controller.hurt).toHaveBeenCalledWith(TUNING.gnorc.damage, e.position);

    stepEnemy(e, 0.05, ctx);
    expect(ctx.controller.hurt).toHaveBeenCalledTimes(1);
  });

  it('misses when the player is beyond attackRange + 0.7', () => {
    const e = makeEnemy({ state: 'strike' });
    const ctx = makeCtx({ player: new THREE.Vector3(3, 0, 0) });
    stepEnemy(e, 0.05, ctx);
    expect(e.struck).toBe(true);
    expect(ctx.controller.hurt).not.toHaveBeenCalled();
  });

  it('fires a projectile instead of hurting directly for ranged enemies', () => {
    const e = makeEnemy({ kind: 'turret', state: 'strike' });
    const ctx = makeCtx({ player: new THREE.Vector3(10, 0, 3) });

    stepEnemy(e, 0.05, ctx);

    expect(ctx.projectiles.fire).toHaveBeenCalledTimes(1);
    expect(ctx.projectiles.fire).toHaveBeenCalledWith(e.position, ctx.player.position, e.meta, MARK);
    expect(ctx.controller.hurt).not.toHaveBeenCalled();
  });

  it('commits a flying dive and drops toward the player', () => {
    const e = makeEnemy({ kind: 'flyer', state: 'strike', position: new THREE.Vector3(0, 4.4, 0) });
    const ctx = makeCtx({ player: new THREE.Vector3(1, 5, 0) });

    stepEnemy(e, 0.1, ctx);

    expect(e.diveTime).toBeCloseTo(0.35, 10); // 0.45 committed, then spent for this frame
    expect(e.position.y).toBeGreaterThan(4.4);
    expect(e.position.y).toBeLessThan(5.6);
    expect(ctx.controller.hurt).toHaveBeenCalledTimes(1);
  });

  it('transitions to recover after the strike duration', () => {
    const e = makeEnemy({ state: 'strike', stateTime: 0.3, struck: true });
    stepEnemy(e, 0.05, makeCtx({ player: new THREE.Vector3(1, 0, 0) }));
    expect(e.state).toBe('recover');
    expect(e.stateTime).toBe(0);
    expect(states(e)).toEqual(['recover']);
  });

  it('tolerates missing controller and projectile services', () => {
    const melee = makeEnemy({ state: 'strike' });
    const ranged = makeEnemy({ kind: 'turret', state: 'strike' });
    const ctx = { ...makeCtx({ player: new THREE.Vector3(1, 0, 0) }), controller: undefined, projectiles: undefined };
    expect(() => stepEnemy(melee, 0.05, ctx)).not.toThrow();
    expect(() => stepEnemy(ranged, 0.05, ctx)).not.toThrow();
    expect(melee.struck).toBe(true);
    expect(ranged.struck).toBe(true);
  });
});

describe('stepEnemy — recover', () => {
  it('sets the post-attack cooldown and chases a visible player', () => {
    const e = makeEnemy({ state: 'recover', stateTime: 0.6 });
    const ctx = makeCtx({ player: new THREE.Vector3(5, 0, 0) });

    stepEnemy(e, 0.03, ctx);

    expect(e.state).toBe('chase');
    expect(e.stateTime).toBe(0);
    expect(e.cooldown).toBeCloseTo(0.32, 10); // 0.35 set on recovery, minus dt
    expect(states(e)).toEqual(['chase']);
  });

  it('return to patrol when the player is no longer visible', () => {
    const e = makeEnemy({ state: 'recover', stateTime: 0.6 });
    stepEnemy(e, 0.03, makeCtx({ player: new THREE.Vector3(30, 0, 0) }));
    expect(e.state).toBe('patrol');
    expect(e.cooldown).toBeCloseTo(0.32, 10);
  });

  it('holds recovery until the full duration has elapsed', () => {
    const e = makeEnemy({ state: 'recover', stateTime: 0.3, locomotion: 5 });
    stepEnemy(e, 0.1, makeCtx({ player: new THREE.Vector3(5, 0, 0) }));
    expect(e.state).toBe('recover');
    expect(e.locomotion).toBeLessThan(5);
    expect(states(e)).toEqual([]);
  });
});

describe('stepEnemy — cooldown and altitude', () => {
  it('ticks the cooldown every active frame and floors it at zero', () => {
    const e = makeEnemy({ state: 'recover', stateTime: 0, cooldown: 0.05, tune: { recover: 10 } });
    stepEnemy(e, 0.1, makeCtx({ player: new THREE.Vector3(5, 0, 0) }));
    expect(e.cooldown).toBe(0);
  });

  it('uses sampled ground height plus the archetype ground offset', () => {
    const e = makeEnemy({ state: 'windup', tune: { windup: 10 }, meta: { groundOffset: 0.4 } });
    const ctx = makeCtx({ player: new THREE.Vector3(0, 0, 10), sampleGround: jest.fn(() => ground(2.4)) });

    stepEnemy(e, 0.1, ctx);

    expect(e.groundY).toBeCloseTo(2.4, 10);
    expect(e.position.y).toBeGreaterThan(1.5);
    expect(e.position.y).toBeLessThan(2.8);
  });

  it('keeps its last ground height when the ground query returns null', () => {
    const e = makeEnemy({ state: 'windup', tune: { windup: 10 }, groundY: 3, position: new THREE.Vector3(0, 1, 0) });
    stepEnemy(e, 0.1, makeCtx({ player: new THREE.Vector3(0, 0, 10), sampleGround: jest.fn(() => null) }));
    expect(e.groundY).toBe(3);
    expect(e.position.y).toBeGreaterThan(1);
    expect(e.position.y).toBeLessThan(3);
  });

  it('hovers around hoverHeight with a phase/time-driven bob', () => {
    const high = makeEnemy({ kind: 'flyer', state: 'patrol', position: new THREE.Vector3(0, 5, 0), phase: Math.PI / 2, tune: { stationary: true } });
    const low = makeEnemy({ kind: 'flyer', state: 'patrol', position: new THREE.Vector3(0, 5, 0), phase: -Math.PI / 2, tune: { stationary: true } });
    const ctx = makeCtx({ player: new THREE.Vector3(100, 0, 0), sampleGround: jest.fn(() => ground(1)) });

    stepEnemy(high, 0.1, ctx);
    stepEnemy(low, 0.1, ctx);

    expect(high.groundY).toBe(1);
    expect(high.position.y).toBeGreaterThan(5);
    expect(low.position.y).toBeLessThan(5);
    expect(high.position.y).toBeGreaterThan(low.position.y);
  });

  it('dives toward the player while diveTime is active and spends the timer', () => {
    const e = makeEnemy({ kind: 'flyer', state: 'strike', struck: true, diveTime: 0.3, position: new THREE.Vector3(0, 4.4, 0) });
    const ctx = makeCtx({ player: new THREE.Vector3(1, 5, 0) });

    stepEnemy(e, 0.1, ctx);

    expect(e.diveTime).toBeCloseTo(0.2, 10);
    expect(e.position.y).toBeGreaterThan(4.4);
    expect(e.position.y).toBeLessThan(5.6);
  });
});

