    expect(box.max.x - box.min.x).toBeCloseTo(2.26, 3);
    expect(box.min.y).toBeCloseTo(-0.36, 3);
    expect(box.max.y).toBeCloseTo(0.35, 3);
    expect(box.min.z).toBeCloseTo(-0.83, 3);
    expect(box.max.z).toBeCloseTo(0.45, 3);

