    expect(geometry.boundingSphere.radius).toBeLessThan(1.2);
  });

  test('assigns vertices to the intended palette slots', () => {
    const { geometry } = build();
    const slots = attr(geometry, 'aSlot');
    const vertexCounts = {};
    const triangleCounts = {};

    for (let i = 0; i < slots.count; i++) {
      const slot = slots.getX(i);
      vertexCounts[slot] = (vertexCounts[slot] || 0) + 1;
    }
    for (let i = 0; i < geometry.index.count; i += 3) {
      const slot = slots.getX(geometry.index.array[i]);
      triangleCounts[slot] = (triangleCounts[slot] || 0) + 1;
    }

    // 0: eye sockets, fangs and claws; 1: skin; 2: cloth; 4: glowing eyes;
    // 5: glowing stinger. No metal is used by this creature.
    expect(vertexCounts).toEqual({
      [SLOT.none]: 202,
      [SLOT.skin]: 292,
      [SLOT.cloth]: 167,
      [SLOT.glowA]: 84,
      [SLOT.glowB]: 13,
