  });

  test('uses literal dark and bone colours only for the unlit features', () => {
    const { geometry } = build();
    const slots = attr(geometry, 'aSlot');

    let darkCount = 0;
    let fangCount = 0;
    for (let i = 0; i < slots.count; i++) {
      const slot = slots.getX(i);
      if (slot === SLOT.none) {
        const dark = colorMatches(geometry, i, DARK_COLOR);
        const fang = colorMatches(geometry, i, FANG_COLOR);
        expect(dark || fang).toBe(true);
        if (dark) darkCount++;
        if (fang) fangCount++;
      } else {
        const [r, g, b] = vertexColor(geometry, i);
        // Palette slots carry only a grey value; hue comes from material uniforms.
        expect(r).toBeCloseTo(g, 6);
        expect(g).toBeCloseTo(b, 6);
      }
    }

    // Two 8x6 eye sockets (112 verts) and 10 hard-edged claws/fangs.
    expect(darkCount).toBe(112);
    expect(fangCount).toBe(90);
  });

  test('places the two glowing eyes on the face and the stinger at the tail', () => {
    const { geometry } = build();
    const slots = attr(geometry, 'aSlot');
    const positions = [];

    for (let i = 0; i < slots.count; i++) {
      if (slots.getX(i) === SLOT.glowA) positions.push(vertexPosition(geometry, i));
    }

    expect(positions).toHaveLength(84);
    const left = positions.filter(([x]) => x > 0);
    const right = positions.filter(([x]) => x < 0);
    expect(left).toHaveLength(42);
    expect(right).toHaveLength(42);
    for (const [x, y, z] of positions) {
      expect(Math.abs(x)).toBeGreaterThan(0.02);
      expect(Math.abs(x)).toBeLessThan(0.13);
      expect(y).toBeGreaterThan(0.02);
      expect(y).toBeLessThan(0.13);
      expect(z).toBeGreaterThan(0.34);
      expect(z).toBeLessThan(0.41);
    }

    const stinger = [];
    for (let i = 0; i < slots.count; i++) {
      if (slots.getX(i) === SLOT.glowB) stinger.push(vertexPosition(geometry, i));
    }
    expect(stinger).toHaveLength(13);
    for (const [x, y, z] of stinger) {
      expect(Math.abs(x)).toBeLessThan(0.04);
      expect(y).toBeLessThan(-0.05);
      expect(z).toBeLessThan(-0.57);
      expect(z).toBeGreaterThanOrEqual(-0.83);
    }
  });
});

describe('buildFlyer() skinning', () => {
