  'thighL',
  'shinL',
  'footL',
  'thighR',
  'shinR',
  'footR',
  'club',
];

const CLIP_CONTRACT = {
  idle: { duration: 3.0, loop: THREE.LoopRepeat, keyframes: 5 },
  walk: { duration: 1.0, loop: THREE.LoopRepeat, keyframes: 9 },
  run: { duration: 0.62, loop: THREE.LoopRepeat, keyframes: 9 },
  alert: { duration: 0.85, loop: THREE.LoopOnce, keyframes: 4 },
  attack: { duration: 0.78, loop: THREE.LoopOnce, keyframes: 5 },
  hurt: { duration: 0.42, loop: THREE.LoopOnce, keyframes: 3 },
  die: { duration: 0.95, loop: THREE.LoopOnce, keyframes: 4 },
  taunt: { duration: 1.3, loop: THREE.LoopOnce, keyframes: 5 },
};

const ATTRIBUTE_LAYOUT = {
  position: 3,
  normal: 3,
  color: 3,
  aSlot: 1,
  skinIndex: 4,
  skinWeight: 4,
};

function arrayOf(geometry, name) {
  return geometry.getAttribute(name).array;
}

function findTrack(clip, trackName) {
  const track = clip.tracks.find((t) => t.name === trackName);
  expect(track).toBeDefined();
  return track;
}

function clipContent(clip) {
  const json = clip.toJSON();
  // Three generates a fresh UUID per AnimationClip; it is not authored content.
  delete json.uuid;
  return json;
}

function valuesAtTime(track, time) {
  const size = track.getValueSize();
  let best = 0;
  for (let i = 1; i < track.times.length; i++) {
    if (Math.abs(track.times[i] - time) < Math.abs(track.times[best] - time)) best = i;
  }
  return Array.from({ length: size }, (_, i) => track.values[best * size + i]);
}

function expectArrayCloseTo(actual, expected, digits = 5) {
  expect(actual).toHaveLength(expected.length);
  actual.forEach((value, i) => expect(value).toBeCloseTo(expected[i], digits));
