function dominantBone(geometry, vertex) {
  const skinIndex = arrayOf(geometry, 'skinIndex');
  const skinWeight = arrayOf(geometry, 'skinWeight');
  const base = vertex * 4;
  let best = 0;
  for (let i = 1; i < 4; i++) {
    if (skinWeight[base + i] > skinWeight[base + best]) best = i;
