    const footR = verticesDominatedBy(geometry, rig.boneIndex.footR);
    expect(footL.length).toBeGreaterThan(0);
    expect(footR.length).toBeGreaterThan(0);
    expect(footL.every((p) => p.x > 0 && p.y <= 0.15)).toBe(true);
    expect(footR.every((p) => p.x < 0 && p.y <= 0.15)).toBe(true);

    const handL = verticesDominatedBy(geometry, rig.boneIndex.handL);
    const handR = verticesDominatedBy(geometry, rig.boneIndex.handR);
