        for (let i = 1; i < track.times.length; i++) {
          expect(track.times[i]).toBeGreaterThanOrEqual(track.times[i - 1]);
        }
        for (let i = 0; i < track.values.length; i++) {
          expect(Number.isFinite(track.values[i])).toBe(true);
        }
