      }
      expect(allTimes.size).toBe(CLIP_CONTRACT[name].keyframes);
    }
  });

  it('closes the locomotion loops seamlessly', () => {
    const { clips } = result;

    for (const name of ['idle', 'walk', 'run']) {
      for (const track of clips[name].tracks) {
        const size = track.getValueSize();
        for (let i = 0; i < size; i++) {
          const first = track.values[i];
          const last = track.values[track.values.length - size + i];
          expect(last).toBeCloseTo(first, 5);
        }
      }
    }
  });

  it('animates vertical root motion for idle sway and reaction poses', () => {
    const { clips } = result;

    const idleRoot = findTrack(clips.idle, 'root.position');
    const idleY = [];
    for (let i = 1; i < idleRoot.values.length; i += 3) idleY.push(idleRoot.values[i]);
    expect(Math.min(...idleY)).toBeCloseTo(0, 5);
    expect(Math.max(...idleY)).toBeCloseTo(0.012, 5);

