  it('exposes the gameplay metadata used by the enemy system', () => {
    expect(result.meta).toEqual({
      kind: 'gnorc',
      height: 1.5,
      radius: 0.55,
      hitHeight: 0.8,
      eyeHeight: 1.2,
      groundOffset: 0,
      scale: 1,
    });
  });

  it('builds a non-empty indexed geometry with a consistent skinning layout', () => {
    const { geometry } = result;
    const vertexCount = geometry.getAttribute('position').count;

    expect(vertexCount).toBeGreaterThan(0);
    for (const [name, itemSize] of Object.entries(ATTRIBUTE_LAYOUT)) {
      const attribute = geometry.getAttribute(name);
      expect(attribute).toBeDefined();
      expect(attribute.itemSize).toBe(itemSize);
      expect(attribute.count).toBe(vertexCount);
    }

    expect(geometry.index).not.toBeNull();
    const indices = geometry.index.array;
    expect(indices.length).toBeGreaterThan(0);
    expect(indices.length % 3).toBe(0);
    for (let i = 0; i < indices.length; i++) {
