  it('stands on the ground and fills the intended short, wide silhouette', () => {
    const { geometry } = result;
    geometry.computeBoundingBox();
    const { min, max } = geometry.boundingBox;

    // The root sits between the feet, exactly on the ground plane.
    expect(min.y).toBeGreaterThanOrEqual(-1e-5);
    expect(min.y).toBeCloseTo(0, 5);

    // The horn is the tallest point, below the nominal 1.5m capsule height.
    expect(max.y).toBeGreaterThan(1.35);
    expect(max.y).toBeLessThanOrEqual(1.5);

    // Arms and the club push the silhouette out well past the body half-width.
    expect(min.x).toBeLessThan(-0.4);
