  it('computes a finite bounding sphere that encloses every vertex', () => {
    const { geometry } = result;
    const sphere = geometry.boundingSphere;
    const position = arrayOf(geometry, 'position');

    expect(sphere).not.toBeNull();
    expect(Number.isFinite(sphere.center.x)).toBe(true);
    expect(Number.isFinite(sphere.center.y)).toBe(true);
    expect(Number.isFinite(sphere.center.z)).toBe(true);
    expect(Number.isFinite(sphere.radius)).toBe(true);
    expect(sphere.radius).toBeGreaterThan(0);

    let maxDistance = 0;
    for (let i = 0; i < position.length; i += 3) {
      const dx = position[i] - sphere.center.x;
      const dy = position[i + 1] - sphere.center.y;
      const dz = position[i + 2] - sphere.center.z;
      maxDistance = Math.max(maxDistance, Math.hypot(dx, dy, dz));
    }
    expect(maxDistance).toBeLessThanOrEqual(sphere.radius + 1e-4);
  });

  it('emits finite positions and unit-length face normals', () => {
    const { geometry } = result;
    const position = arrayOf(geometry, 'position');
    const normal = arrayOf(geometry, 'normal');

    let maxNormalError = 0;
    for (let i = 0; i < position.length; i++) {
      expect(Number.isFinite(position[i])).toBe(true);
      expect(Number.isFinite(normal[i])).toBe(true);
    }
    for (let i = 0; i < normal.length; i += 3) {
      const length = Math.hypot(normal[i], normal[i + 1], normal[i + 2]);
      maxNormalError = Math.max(maxNormalError, Math.abs(length - 1));
    }
    expect(maxNormalError).toBeLessThan(1e-5);
  });

  it('normalizes every vertex to at most four valid rig bones', () => {
    const { geometry, rig } = result;
    const skinIndex = arrayOf(geometry, 'skinIndex');
    const skinWeight = arrayOf(geometry, 'skinWeight');
    const vertexCount = geometry.getAttribute('position').count;
    const usedBones = new Set();

    let maxWeightError = 0;
    for (let v = 0; v < vertexCount; v++) {
      const base = v * 4;
      let sum = 0;
      for (let i = 0; i < 4; i++) {
        const weight = skinWeight[base + i];
        const bone = skinIndex[base + i];
        expect(Number.isFinite(weight)).toBe(true);
        expect(weight).toBeGreaterThanOrEqual(0);
        expect(Number.isInteger(bone)).toBe(true);
        expect(bone).toBeGreaterThanOrEqual(0);
        expect(bone).toBeLessThan(rig.names.length);
        sum += weight;
        usedBones.add(bone);
      }
      maxWeightError = Math.max(maxWeightError, Math.abs(sum - 1));
    }
    expect(maxWeightError).toBeLessThan(1e-5);

    // Every declared bone drives part of the skin, including the club.
    expect([...usedBones].sort((a, b) => a - b)).toEqual(
