    const hurtRoot = findTrack(clips.hurt, 'root.position');
    expectArrayCloseTo(valuesAtTime(hurtRoot, 0.1), [0, 0.05, 0]);

    const dieRoot = findTrack(clips.die, 'root.position');
    expectArrayCloseTo(valuesAtTime(dieRoot, 0.14), [0, 0.2, 0]);
