  it('adds squash-and-stretch keys to the reaction clips', () => {
    const { clips } = result;

    expectArrayCloseTo(valuesAtTime(findTrack(clips.alert, 'belly.scale'), 0.11), [0.9, 1.16, 0.9]);
    expectArrayCloseTo(valuesAtTime(findTrack(clips.alert, 'belly.scale'), 0.32), [1.08, 0.94, 1.08]);

    expectArrayCloseTo(valuesAtTime(findTrack(clips.hurt, 'belly.scale'), 0.1), [1.14, 0.86, 1.14]);

    expectArrayCloseTo(valuesAtTime(findTrack(clips.taunt, 'belly.scale'), 0.3), [1.12, 0.94, 1.12]);
    expectArrayCloseTo(valuesAtTime(findTrack(clips.taunt, 'belly.scale'), 0.52), [0.94, 1.08, 0.94]);

    // The one-shot clips start and finish in neutral squash.
    for (const name of ['alert', 'hurt', 'taunt']) {
      const track = findTrack(clips[name], 'belly.scale');
      expectArrayCloseTo(valuesAtTime(track, 0), [1, 1, 1]);
      expectArrayCloseTo(valuesAtTime(track, CLIP_CONTRACT[name].duration), [1, 1, 1]);
    }
  });

  it('swings the club through a full attack arc', () => {
    const { clips } = result;
    const club = findTrack(clips.attack, 'club.quaternion');
    const size = club.getValueSize();

    const first = Array.from({ length: size }, (_, i) => club.values[i]);
    const last = Array.from({ length: size }, (_, i) => club.values[club.values.length - size + i]);
    expectArrayCloseTo(last, first);

    let maxDelta = 0;
    for (let i = 0; i < size; i++) {
      maxDelta = Math.max(maxDelta, Math.abs(club.values[size + i] - first[i]));
    }
    expect(maxDelta).toBeGreaterThan(0.4);
  });

  it('is deterministic while returning fresh mutable assets per build', () => {
    const first = buildGnorc();
    const second = buildGnorc();

    expect(second).not.toBe(first);
    expect(second.rig).not.toBe(first.rig);
    expect(second.geometry).not.toBe(first.geometry);
    expect(second.clips).not.toBe(first.clips);

    for (const name of Object.keys(ATTRIBUTE_LAYOUT)) {
      expect(Array.from(arrayOf(second.geometry, name))).toEqual(
        Array.from(arrayOf(first.geometry, name))
      );
    }
    expect(Array.from(second.geometry.index.array)).toEqual(
