flameBurst(origin, dir, strength = 1) {
    if (!this.addPool || !this.enabled) return;
    const rnd = this.rnd;
    const p = this.p;
    const t = this.time;
    const b = this._biome();
    const add = this.addPool;
    const alpha = this.alphaPool;

    this._basis(dir ?? this._dir);
    const ox = origin.x, oy = origin.y, oz = origin.z;

    // Ground under the cone tip: fire that licks the floor should dissolve
    // into it rather than stab through it.
    const tipX = ox + _dz.x * 2.4;
    const tipZ = oz + _dz.z * 2.4;
    const gY = this._groundY(tipX, tipZ, oy - 40) - 0.12;

    const nf = 38 * strength * this.budget + this._flame.frac;
    const n = nf | 0;
    this._flame.frac = nf - n;
    if (n <= 0) return;

    // Outer flame carries a whisper of the realm's accent so it sits in key.
    _c1.copy(FIRE_LOW).lerp(_c0.set(b.accent), 0.15);
    const outerHex = _c1.getHex();

    // ---- core cone ----------------------------------------------------
    for (let i = 0; i < n; i++) {
      resetEmitParams(p);
      const a = rnd() * TAU;
      const rad = Math.sqrt(rnd()) * 0.14;
      const spread = 0.13 + rnd() * 0.20;
      const sp = 12.5 + rnd() * 9.5;
      const along = 0.04 + rnd() * 0.34;
      p.x = ox + _dz.x * along + (_dx.x * Math.cos(a) + _dy.x * Math.sin(a)) * rad;
      p.y = oy + _dz.y * along + (_dx.y * Math.cos(a) + _dy.y * Math.sin(a)) * rad;
      p.z = oz + _dz.z * along + (_dx.z * Math.cos(a) + _dy.z * Math.sin(a)) * rad;
      const lat = spread * sp * 0.55;
      p.vx = _dz.x * sp + (_dx.x * Math.cos(a) + _dy.x * Math.sin(a)) * lat;
      p.vy = _dz.y * sp + (_dx.y * Math.cos(a) + _dy.y * Math.sin(a)) * lat + 1.1;
      p.vz = _dz.z * sp + (_dx.z * Math.cos(a) + _dy.z * Math.sin(a)) * lat;
      p.life = 0.30 + rnd() * 0.26;
      p.size0 = 0.15 + rnd() * 0.12;
      p.size1 = 0.85 + rnd() * 0.75;
      // Hottest at the muzzle, cooling with distance down the cone.
      _c0.copy(FIRE_HOT).lerp(FIRE_MID, along * 1.4 + rnd() * 0.35);
      p.r0 = _c0.r; p.g0 = _c0.g; p.b0 = _c0.b;
      p.intensity = 3.4 + rnd() * 2.4;
      this._end(outerHex, 0.9);
      p.tile = TILE.GLOW;
      p.mode = MODE.BILLBOARD;
      p.rot = rnd() * TAU;
      p.spin = (rnd() - 0.5) * 5.0;
      p.seed = rnd();
      p.drag = 2.6 + rnd() * 1.6;
      p.gravity = 3.0;
      p.turb = 1.5 + rnd() * 1.6;
      p.groundY = gY;
      add.emit(p, t);
    }

    // ---- pressurised jet at the mouth ---------------------------------
    const nJet = Math.max(1, (n * 0.28) | 0);
    for (let i = 0; i < nJet; i++) {
      resetEmitParams(p);
      const a = rnd() * TAU;
      const rad = rnd() * 0.06;
      const sp = 21 + rnd() * 11;
      p.x = ox + (_dx.x * Math.cos(a) + _dy.x * Math.sin(a)) * rad;
      p.y = oy + (_dx.y * Math.cos(a) + _dy.y * Math.sin(a)) * rad;
      p.z = oz + (_dx.z * Math.cos(a) + _dy.z * Math.sin(a)) * rad;
      p.vx = _dz.x * sp; p.vy = _dz.y * sp; p.vz = _dz.z * sp;
      p.life = 0.10 + rnd() * 0.09;
      p.size0 = 0.10 + rnd() * 0.07;
      p.size1 = 0.30 + rnd() * 0.18;
      this._start(FIRE_HOT.getHex(), 5.5 + rnd() * 2.5);
      this._end(FIRE_MID.getHex(), 1.0);
      p.tile = TILE.STREAK;
      p.mode = MODE.STRETCH;
      p.seed = rnd();
      p.drag = 4.5;
      p.groundY = gY;
      add.emit(p, t);
    }

    // ---- embers that outlive the cone ---------------------------------
    const nEm = Math.max(1, (n * 0.34) | 0);
    for (let i = 0; i < nEm; i++) {
      resetEmitParams(p);
      const a = rnd() * TAU;
      const spread = 0.25 + rnd() * 0.5;
      const sp = 5 + rnd() * 14;
      const along = 0.2 + rnd() * 1.5;
      p.x = ox + _dz.x * along;
      p.y = oy + _dz.y * along;
      p.z = oz + _dz.z * along;
      const lat = spread * sp * 0.8;
      p.vx = _dz.x * sp + (_dx.x * Math.cos(a) + _dy.x * Math.sin(a)) * lat;
      p.vy = _dz.y * sp + (_dx.y * Math.cos(a) + _dy.y * Math.sin(a)) * lat + 2.2;
      p.vz = _dz.z * sp + (_dx.z * Math.cos(a) + _dy.z * Math.sin(a)) * lat;
      p.life = 0.6 + rnd() * 0.95;
      p.size0 = 0.05 + rnd() * 0.07;
      p.size1 = 0.012;
      this._start(FIRE_MID.getHex(), 3.6 + rnd() * 2.2);
      this._end(FIRE_DEAD.getHex(), 1.0);
      p.tile = rnd() < 0.3 ? TILE.STAR : TILE.GLOW;
      p.mode = rnd() < 0.45 ? MODE.STRETCH : MODE.BILLBOARD;
      p.rot = rnd() * TAU;
      p.spin = (rnd() - 0.5) * 8;
      p.seed = rnd();
      p.drag = 0.55 + rnd() * 0.8;
      p.gravity = -8.5;
      p.turb = 0.9;
      p.groundY = gY;
      add.emit(p, t);
    }

    // ---- lingering smoke ----------------------------------------------
    const nSm = Math.max(1, (n * 0.30) | 0);
    for (let i = 0; i < nSm; i++) {
      resetEmitParams(p);
      const a = rnd() * TAU;
      const along = 0.7 + rnd() * 2.4;
      const lat = 0.15 + rnd() * 0.55;
      p.x = ox + _dz.x * along + (_dx.x * Math.cos(a) + _dy.x * Math.sin(a)) * lat;
      p.y = oy + _dz.y * along + (_dx.y * Math.cos(a) + _dy.y * Math.sin(a)) * lat;
      p.z = oz + _dz.z * along + (_dx.z * Math.cos(a) + _dy.z * Math.sin(a)) * lat;
      const sp = 1.4 + rnd() * 3.4;
      p.vx = _dz.x * sp + (rnd() - 0.5) * 1.2;
      p.vy = _dz.y * sp + 0.5 + rnd() * 0.8;
      p.vz = _dz.z * sp + (rnd() - 0.5) * 1.2;
      p.life = 1.1 + rnd() * 1.1;
      p.size0 = 0.35 + rnd() * 0.35;
      p.size1 = 1.7 + rnd() * 1.4;
      // Smoke belongs to the place, so it is graded off the biome's fog.
      _c0.set(b.fog.color).multiplyScalar(0.30);
      p.r0 = _c0.r; p.g0 = _c0.g; p.b0 = _c0.b;
      p.intensity = 1;
      _c1.set(b.fog.color).multiplyScalar(0.85);
      p.r1 = _c1.r; p.g1 = _c1.g; p.b1 = _c1.b;
      p.alpha = 0.16 + rnd() * 0.16;
      p.tile = TILE.SMOKE;
      p.mode = MODE.BILLBOARD;
      p.rot = rnd() * TAU;
      p.spin = (rnd() - 0.5) * 1.1;
      p.seed = rnd();
      p.drag = 1.5;
      p.gravity = 1.5;
      p.turb = 0.55;
      p.groundY = gY;
      alpha.emit(p, t);
    }

    // ---- muzzle flash ring ---------------------------------------------
    this._flame.ring -= strength;
    if (this._flame.ring <= 0) {
      this._flame.ring = 0.32;
      resetEmitParams(p);
