update(dt, ctx) {
    const p = this.player;
    const input = ctx.input;
    const world = ctx.world;

    this.iframes = Math.max(0, this.iframes - dt);
    this.coyote = Math.max(0, this.coyote - dt);
    this.jumpBuffer = Math.max(0, this.jumpBuffer - dt);
    if (input.pressed('jump')) this.jumpBuffer = JUMP_BUFFER;

    if (p.state === 'dead') {
      this.deadTime += dt;
      p.velocity.y += GRAVITY * dt;
      p.position.addScaledVector(p.velocity, dt);
      const g = world.sampleGround(p.position.x, p.position.z);
      if (g && p.position.y < g.y) {
        p.position.y = g.y;
        p.velocity.set(0, 0, 0);
      }
      if (this.deadTime > 2.2) {
        if (p.lives > 0) {
          p.health = p.maxHealth;
          this.respawn(this.lastGroundPos);
        } else {
          ctx.events.emit('mission:failed', {});
          p.lives = 3;
          p.health = p.maxHealth;
          this.respawn(this.lastGroundPos);
        }
      }
      return;
    }

    const desired = this._desiredDir(_v2);
    const hasInput = desired.lengthSq() > 0.0001;
    if (hasInput) desired.normalize();

    // ---------------------------------------------------------- state ----
    const wantCharge = input.down('charge') && (p.state === 'ground' || p.state === 'charge');
    const wantFlame = input.pressed('flame');

    if (this.hurtTime > 0) {
      this.hurtTime -= dt;
      if (this.hurtTime <= 0 && p.state === 'hurt') p.state = p.grounded ? 'ground' : 'air';
    }

    if (this.flameTime > 0) {
      this.flameTime -= dt;
      if (this.flameTime <= 0) {
        ctx.events.emit('player:flame', { on: false });
        if (p.state === 'flame') p.state = p.grounded ? 'ground' : 'air';
      }
    } else if (wantFlame && p.state !== 'hurt' && p.state !== 'glide') {
      this.flameTime = 0.55;
      p.state = 'flame';
      const origin = new THREE.Vector3();
      if (ctx.dragon) ctx.dragon.mouthWorldPosition(origin);
      else origin.copy(p.position).addScaledVector(p.forward, 0.9).setY(p.position.y + 0.9);
      ctx.events.emit('player:flame', { on: true, origin, dir: p.forward.clone() });
    }

    // ------------------------------------------------------- horizontal ----
    let targetSpeed = 0;
    let accel = p.grounded ? GROUND_ACCEL : AIR_ACCEL;

    if (p.state === 'charge') {
      targetSpeed = CHARGE_SPEED;
      this.chargeTime += dt;
      // Charge steers, it doesn't stop. Release or hit something to exit.
      if (hasInput) {
        const targetYaw = Math.atan2(desired.x, desired.z);
        p.yaw = approachAngle(p.yaw, targetYaw, 3.4 * dt);
      }
      if (!input.down('charge') || this.chargeTime > 4) {
        p.state = p.grounded ? 'ground' : 'air';
        this.chargeTime = 0;
        ctx.events.emit('player:charge', { on: false });
      }
    } else if (wantCharge && p.grounded && hasInput) {
      p.state = 'charge';
      this.chargeTime = 0;
      ctx.events.emit('player:charge', { on: true });
      targetSpeed = CHARGE_SPEED;
    } else if (p.state === 'glide') {
      targetSpeed = GLIDE_SPEED;
      // Glide turns are wide and committed.
      this.turnInput = damp(this.turnInput, input.move.x, 8, dt);
      p.yaw -= this.turnInput * GLIDE_TURN_RATE * dt;
      if (input.move.y < -0.4) targetSpeed *= 0.72;
    } else if (p.state === 'flame') {
      targetSpeed = hasInput ? RUN_SPEED * 0.35 : 0;
      if (hasInput) p.yaw = approachAngle(p.yaw, Math.atan2(desired.x, desired.z), TURN_RATE * 0.5 * dt);
    } else if (p.state === 'hurt') {
      targetSpeed = 0;
      accel = 8;
    } else if (hasInput) {
      const sprint = input.down('charge');
      targetSpeed = sprint ? SPRINT_SPEED : RUN_SPEED * (0.35 + 0.65 * ctx.input.move.length());
      const targetYaw = Math.atan2(desired.x, desired.z);
      p.yaw = approachAngle(p.yaw, targetYaw, TURN_RATE * dt * (p.grounded ? 1 : 0.55));
    }

    p.forward.set(Math.sin(p.yaw), 0, Math.cos(p.yaw));

    const horiz = _v.set(p.velocity.x, 0, p.velocity.z);
    const targetVel = _v2.copy(p.forward).multiplyScalar(targetSpeed);
    if (p.state === 'glide' || p.state === 'charge') {
      horiz.lerp(targetVel, 1 - Math.exp(-accel * 0.35 * dt));
    } else {
      const k = 1 - Math.exp(-accel * dt * (targetSpeed > 0 ? 1 : 1.6));
      horiz.lerp(targetVel, k);
    }
    p.velocity.x = horiz.x;
    p.velocity.z = horiz.z;
    p.speed = Math.hypot(p.velocity.x, p.velocity.z);

    // --------------------------------------------------------- vertical ----
    if (p.state === 'glide') {
      this.glideTime += dt;
      // Fixed sink rate — the whole point is that the player can predict it.
      p.velocity.y = damp(p.velocity.y, GLIDE_FALL, 6, dt);
      if (this.hoverTime > 0) {
        this.hoverTime -= dt;
        p.velocity.y = HOVER_BOOST * (this.hoverTime / 0.42);
      }
      if (this.jumpBuffer > 0 && this.hoverTime <= 0 && !this._hoverUsed) {
        this._hoverUsed = true;
        this.hoverTime = 0.42;
        this.jumpBuffer = 0;
        ctx.events.emit('player:hover', {});
      }
      if (input.down('charge')) {
        // Dive out of a glide.
        p.velocity.y = -16;
        p.state = 'air';
        ctx.events.emit('player:glide', { on: false });
      }
    } else {
      p.velocity.y += GRAVITY * dt;
    }

    // Updrafts lift you regardless of state, but only really pay off in a glide.
    for (const up of world.updrafts) {
      const d = Math.hypot(p.position.x - up.x, p.position.z - up.z);
      if (d < up.r && p.position.y < up.topY && p.position.y > up.baseY - 6) {
        const falloff = 1 - d / up.r;
        const lift = up.strength * falloff * (p.state === 'glide' ? 1.25 : 0.8);
        p.velocity.y = Math.min(p.velocity.y + lift * dt, 17);
      }
    }

    // ------------------------------------------------------------- jump ----
    if (this.jumpBuffer > 0 && p.state !== 'glide' && p.state !== 'hurt') {
      if (p.grounded || this.coyote > 0) {
        p.velocity.y = JUMP_VELOCITY;
        p.grounded = false;
        this.coyote = 0;
        this.jumpBuffer = 0;
        this.jumpCount = 1;
        this._hoverUsed = false;
        p.state = 'air';
        ctx.events.emit('player:jump', { position: p.position.clone(), double: false });
      } else if (this.jumpCount === 1 && p.velocity.y < 5) {
        // Second press in the air starts the glide — the Spyro signature.
        this.jumpCount = 2;
        this.jumpBuffer = 0;
        this.glideTime = 0;
        this._hoverUsed = false;
        p.state = 'glide';
        p.velocity.y = Math.max(p.velocity.y, -1.5);
        ctx.events.emit('player:glide', { on: true });
        ctx.events.emit('player:jump', { position: p.position.clone(), double: true });
      }
    }

    // -------------------------------------------------------- integrate ----
    _v.copy(p.velocity).multiplyScalar(dt);
    this._moveWithCollision(_v, world);

    // ----------------------------------------------------------- ground ----
    const g = world.sampleGround(p.position.x, p.position.z);
    const wasGrounded = p.grounded;
    if (g) {
      const foot = g.y;
      if (p.position.y <= foot + 0.06 && p.velocity.y <= 0.5) {
        const impact = -p.velocity.y;
        p.position.y = foot;
        p.velocity.y = 0;
        p.grounded = true;
        p.groundNormal.copy(g.normal);
        p.islandId = g.islandId;
        if (g.biome !== p.biome) {
          p.biome = g.biome;
          ctx.events.emit('player:enterIsland', { island: g.island, biome: g.biome });
        }
        this.coyote = COYOTE_TIME;
        this.lastGroundPos.set(p.position.x, p.position.y, p.position.z);

        if (!wasGrounded) {
          this.jumpCount = 0;
          this._hoverUsed = false;
          const wasGliding = p.state === 'glide';
          if (p.state !== 'hurt') p.state = 'ground';
          if (wasGliding) ctx.events.emit('player:glide', { on: false });
          ctx.events.emit('player:land', { position: p.position.clone(), speed: impact, biome: g.biome });
        }

        // Slide off anything too steep.
        if (g.slope > MAX_SLOPE) {
          _v2.set(g.normal.x, 0, g.normal.z).normalize().multiplyScalar(14 * dt * (g.slope - MAX_SLOPE) * 4);
          p.velocity.add(_v2);
          p.grounded = false;
        }
      } else {
        p.grounded = false;
      }
    } else {
      p.grounded = false;
    }

    if (!p.grounded && p.state !== 'glide' && p.state !== 'charge' && p.state !== 'hurt' && p.state !== 'flame') {
      p.state = 'air';
    }
    if (p.grounded && p.state === 'charge') this.chargeTime += 0;

    // ----------------------------------------------------- fall-out ----
    if (p.position.y < ctx.graph.killPlaneY) {
      this.hurt(1, null);
      if (p.state !== 'dead') this.respawn(this.lastGroundPos);
    }
  }

