constructor(ctx) {
    this.ctx = ctx;
    this.player = {
      position: new THREE.Vector3(),
      velocity: new THREE.Vector3(),
      forward: new THREE.Vector3(0, 0, 1),
      yaw: 0,
      state: 'ground',
      grounded: true,
      health: 4,
      maxHealth: 4,
      lives: 3,
      speed: 0,
      islandId: -1,
      biome: null,
      canGlide: false,
      groundNormal: new THREE.Vector3(0, 1, 0),
    };
    this.coyote = 0;
    this.jumpBuffer = 0;
    this.jumpCount = 0;
    this.glideTime = 0;
    this.hoverTime = 0;
    this.chargeTime = 0;
    this.flameTime = 0;
    this.hurtTime = 0;
    this.iframes = 0;
    this.deadTime = 0;
    this.lastGroundPos = new THREE.Vector3();
    this.turnInput = 0;
  }

