  test('does not fill the jump buffer when jump is not pressed', () => {
    const { controller, ctx, player } = makeHarness();
    pose(player, { state: 'air', grounded: false });
    controller.jumpBuffer = 0;

    controller.update(0.05, ctx);

    expect(controller.jumpBuffer).toBe(0);
  });
});

