describe('Controller.update — gliding', () => {
  test('a glide sinks toward the fixed glide fall rate and tracks glide time', () => {
    const { controller, ctx, player } = makeHarness();
    pose(player, { state: 'glide', grounded: false, velocity: [0, -10, 0] });
    controller._hoverUsed = true;

    controller.update(0.1, ctx);

    // moved toward the fixed sink rate but not past it
    expect(player.velocity.y).toBeGreaterThan(-10);
    expect(player.velocity.y).toBeLessThan(-3.1);
    expect(controller.glideTime).toBeCloseTo(0.1, 10);
    expect(player.state).toBe('glide');
  });

  test('a buffered jump during a glide triggers a single hover', () => {
    const { controller, ctx, player, events } = makeHarness();
    pose(player, { state: 'glide', grounded: false, velocity: [0, -3, 0] });
    controller.jumpBuffer = 0.1;
    controller.hoverTime = 0;

    controller.update(0.016, ctx);

    expect(events.names()).toContain('player:hover');
    expect(controller.hoverTime).toBeCloseTo(0.42, 10);
    expect(controller.jumpBuffer).toBe(0);
    expect(controller._hoverUsed).toBe(true);
    // hovering must not be consumed as a normal jump
    expect(events.names()).not.toContain('player:jump');
  });

  test('hover is only available once per glide', () => {
    const { controller, ctx, player, events } = makeHarness();
    pose(player, { state: 'glide', grounded: false, velocity: [0, -3, 0] });
    controller.jumpBuffer = 0.1;
    controller._hoverUsed = true;

    controller.update(0.016, ctx);

    expect(events.names()).not.toContain('player:hover');
    expect(controller.hoverTime).toBe(0);
  });

  test('hovering pushes the player up while the hover window lasts', () => {
    const { controller, ctx, player } = makeHarness();
    pose(player, { state: 'glide', grounded: false, velocity: [0, -3.1, 0] });
    controller.hoverTime = 0.42;
    controller._hoverUsed = true;

    controller.update(0.1, ctx);

    expect(player.velocity.y).toBeGreaterThan(0);
    expect(controller.hoverTime).toBeCloseTo(0.32, 10);
  });

  test('a glide leans into the stick with damped, committed turning', () => {
    const { controller, ctx, player } = makeHarness({
      input: makeInput({ move: [1, 0] }),
    });
    pose(player, { state: 'glide', grounded: false, velocity: [0, -3.1, 0], yaw: 0 });
    controller._hoverUsed = true;

    controller.update(0.1, ctx);

    // "right" of a +Z camera is -X, so yaw must move negative
    expect(player.yaw).toBeLessThan(0);
    expect(controller.turnInput).toBeGreaterThan(0);
    expect(controller.turnInput).toBeLessThan(1);
    expect(player.state).toBe('glide');
  });

  test('pulling the stick back slows a glide to 72% of glide speed', () => {
    const forwardHarness = makeHarness({ input: makeInput({ move: [0, 1] }) });
    pose(forwardHarness.player, { state: 'glide', grounded: false, velocity: [0, -3.1, 0], yaw: 0 });
    forwardHarness.controller._hoverUsed = true;
    run(forwardHarness.controller, forwardHarness.ctx, 80, 0.016);

    const brakeHarness = makeHarness({ input: makeInput({ move: [0, -1] }) });
    pose(brakeHarness.player, { state: 'glide', grounded: false, velocity: [0, -3.1, 0], yaw: 0 });
    brakeHarness.controller._hoverUsed = true;
    run(brakeHarness.controller, brakeHarness.ctx, 80, 0.016);

    expect(forwardHarness.player.speed).toBeCloseTo(10.5, 1);
    expect(brakeHarness.player.speed).toBeCloseTo(10.5 * 0.72, 1);
    expect(brakeHarness.player.speed).toBeLessThan(forwardHarness.player.speed);
  });

  test('holding charge dives out of a glide', () => {
    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ down: { charge: true } }),
    });
    pose(player, { state: 'glide', grounded: false, velocity: [0, -3, 0] });
    controller._hoverUsed = true;

    controller.update(0.016, ctx);

    expect(player.velocity.y).toBe(-16);
    expect(player.state).toBe('air');
    expect(events.payloads('player:glide')).toEqual([{ on: false }]);
  });
});

