  });

  test('uses the camera basis rather than world axes for direction', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player } = makeHarness({
      input: makeInput({ move: [1, 0] }),
      world: makeWorld({ ground }),
      forward: [1, 0, 0], // camera looks down +X, so "right" is +Z
    });
    pose(player, { position: [0, 0, 0], state: 'ground', grounded: true, yaw: 0 });

    run(controller, ctx, 60, 0.016);

    expect(player.velocity.z).toBeCloseTo(RUN_SPEED, 3);
    expect(Math.abs(player.velocity.x)).toBeLessThan(0.01);
  });

  test('partial stick deflection yields a proportionally slower run', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player } = makeHarness({
      input: makeInput({ move: [0, 0.5] }),
      world: makeWorld({ ground }),
    });
