    const { controller, ctx, player } = makeHarness();
    pose(player, { state: 'air', grounded: false, velocity: [3, 0, 0] });

    run(controller, ctx, 80, 0.016);

    expect(player.speed).toBeLessThan(0.01);
  });
});

