/**
 * Behavioural tests for Controller.update(dt, ctx).
 *
 * The target is exercised through its only callable entry point. Every external
 * boundary (input device, terrain queries, event bus, camera, dragon model) is a
 * lightweight deterministic double so the tests assert the controller's own
 * observable contract: player state, velocity, emitted events and side effects.
 */
import { jest } from '@jest/globals';
import * as THREE from 'three';
import { Controller } from '../../../src/play/Controller.js';

// Tuning values that the target's observable behaviour is expressed in.
const GRAVITY = -26;
const RUN_SPEED = 8.4;
const SPRINT_SPEED = 11.5;
const CHARGE_SPEED = 15.5;
const JUMP_VELOCITY = 10.2;
const COYOTE_TIME = 0.13;
const JUMP_BUFFER = 0.14;
const PLAYER_RADIUS = 0.55;

const DT = 0.1;

/* ------------------------------------------------------------------ doubles */

function makeInput({ move = [0, 0], down = {}, pressed = {} } = {}) {
  return {
    move: new THREE.Vector2(move[0], move[1]),
    look: new THREE.Vector2(),
    down: jest.fn((action) => down[action] === true),
    pressed: jest.fn((action) => pressed[action] === true),
    released: jest.fn(() => false),
  };
}

function makeGround({
  y = 0,
  slope = 0,
  normal = new THREE.Vector3(0, 1, 0),
  islandId = 1,
  biome = 'meadow',
  island = { id: 'island-1' },
} = {}) {
  return { y, slope, normal: normal.clone(), island, islandId, biome };
}

function makeWorld({ ground = null, updrafts = [], blockers = [] } = {}) {
  return {
    sampleGround: jest.fn(() => ground),
    updrafts,
    blockers,
  };
}

function makeHarness(options = {}) {
  const calls = [];
  const events = {
    emit: jest.fn((name, payload) => {
      calls.push([name, payload]);
    }),
    names: () => calls.map((c) => c[0]),
    payloads: (name) => calls.filter((c) => c[0] === name).map((c) => c[1]),
  };

  const ctx = {
    input: options.input || makeInput(),
    world: options.world || makeWorld(),
    events,
    engine: {
      camera: {
        getWorldDirection: (out) => out.set(...(options.forward || [0, 0, 1])),
      },
    },
    graph: { killPlaneY: options.killPlaneY === undefined ? -50 : options.killPlaneY },
  };
  if (options.dragon) ctx.dragon = options.dragon;
  if (options.fx) ctx.fx = options.fx;

  const controller = new Controller(ctx);
  return { controller, ctx, player: controller.player, events };
}

/** Put the player into a known pose. Anything not supplied keeps its default. */
function pose(player, overrides = {}) {
  if (overrides.position) player.position.set(...overrides.position);
  if (overrides.velocity) player.velocity.set(...overrides.velocity);
  if (overrides.forward) player.forward.set(...overrides.forward);
  if (overrides.state !== undefined) player.state = overrides.state;
  if (overrides.grounded !== undefined) player.grounded = overrides.grounded;
  if (overrides.yaw !== undefined) player.yaw = overrides.yaw;
  return player;
}

function run(controller, ctx, frames, dt = DT) {
  for (let i = 0; i < frames; i++) controller.update(dt, ctx);
}

/* --------------------------------------------------------------- timers --- */

describe('Controller.update — timers', () => {
  test('decrements invulnerability, coyote time and jump buffer by dt', () => {
    // hurt blocks the jump so the buffered value survives to be observed
    const { controller, ctx, player } = makeHarness();
    pose(player, { state: 'hurt', grounded: false });
    controller.hurtTime = 5;
    controller.iframes = 0.5;
    controller.coyote = 0.5;
    controller.jumpBuffer = 0.5;

    controller.update(0.1, ctx);

    expect(controller.iframes).toBeCloseTo(0.4, 10);
    expect(controller.coyote).toBeCloseTo(0.4, 10);
    expect(controller.jumpBuffer).toBeCloseTo(0.4, 10);
  });

  test('clamps timers at zero instead of going negative', () => {
    const { controller, ctx, player } = makeHarness();
    pose(player, { state: 'air', grounded: false });
    controller.iframes = 0.01;
    controller.coyote = 0.01;
    controller.jumpBuffer = 0.01;

    controller.update(0.1, ctx);

    expect(controller.iframes).toBe(0);
    expect(controller.coyote).toBe(0);
    expect(controller.jumpBuffer).toBe(0);
  });

  test('a jump press fills the jump buffer even when the jump is blocked', () => {
    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ pressed: { jump: true } }),
    });
    pose(player, { state: 'hurt', grounded: true });
    controller.hurtTime = 5;

    controller.update(0.05, ctx);

    // the timed decay happens first, then a fresh press refills the buffer
    expect(controller.jumpBuffer).toBeCloseTo(JUMP_BUFFER, 10);
    expect(events.names()).not.toContain('player:jump');
    expect(ctx.input.pressed).toHaveBeenCalledWith('jump');
  });

  test('does not fill the jump buffer when jump is not pressed', () => {
    const { controller, ctx, player } = makeHarness();
    pose(player, { state: 'air', grounded: false });
    controller.jumpBuffer = 0;

    controller.update(0.05, ctx);

    expect(controller.jumpBuffer).toBe(0);
  });
});

/* ----------------------------------------------------------- dead state --- */

describe('Controller.update — dead state', () => {
  test('applies gravity, advances deadTime and ignores input while dead', () => {
