      input: makeInput({ pressed: { jump: true, flame: true }, move: [0, 1] }),
    });
    pose(player, { position: [0, 10, 0], velocity: [0, 0, 0], state: 'dead', grounded: false });
    controller.deadTime = 0;

    controller.update(0.5, ctx);

    expect(controller.deadTime).toBeCloseTo(0.5, 10);
    // gravity for half a second
    expect(player.velocity.y).toBeCloseTo(GRAVITY * 0.5, 10);
    expect(player.position.y).toBeCloseTo(10 + GRAVITY * 0.5 * 0.5, 10);
    // the dead branch returns before any state-machine gameplay runs
    expect(events.names()).not.toContain('player:jump');
    expect(events.names()).not.toContain('player:flame');
    expect(player.state).toBe('dead');
  });

  test('the dead body settles on the ground instead of falling through it', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player } = makeHarness({ world: makeWorld({ ground }) });
    pose(player, { position: [0, -1, 0], velocity: [0, -4, 0], state: 'dead', grounded: false });

    controller.update(0.1, ctx);

    expect(player.position.y).toBe(0);
    expect(player.velocity.length()).toBe(0);
  });

  test('respawns with full health once the death timer passes 2.2s and lives remain', () => {
