    player.lives = 0;
    player.health = 0;
    controller.deadTime = 2.2;

    controller.update(0.05, ctx);

    expect(events.names()).toContain('mission:failed');
    expect(events.names()).toContain('player:respawn');
    expect(player.lives).toBe(3);
    expect(player.health).toBe(player.maxHealth);
  });
});

