describe('Controller.update — flame breath', () => {
  test('starts a flame and reports the mouth origin when no dragon model exists', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ pressed: { flame: true } }),
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0, 0], state: 'ground', grounded: true });

    controller.update(0.016, ctx);

    expect(controller.flameTime).toBeCloseTo(0.55, 10);
    expect(player.state).toBe('flame');
    const [flame] = events.payloads('player:flame');
    expect(flame.on).toBe(true);
    // fallback origin: one unit ahead and chest height
    expect(flame.origin.x).toBeCloseTo(0, 10);
    expect(flame.origin.y).toBeCloseTo(0.9, 10);
    expect(flame.origin.z).toBeCloseTo(0.9, 10);
    expect(flame.dir.x).toBeCloseTo(0, 10);
    expect(flame.dir.z).toBeCloseTo(1, 10);
  });

  test('uses the dragon mouth position when a dragon collaborator is present', () => {
    const ground = makeGround({ y: 0 });
    const dragon = { mouthWorldPosition: jest.fn((out) => out.set(4, 5, 6)) };
    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ pressed: { flame: true } }),
      world: makeWorld({ ground }),
      dragon,
    });
    pose(player, { position: [0, 0, 0], state: 'ground', grounded: true });

    controller.update(0.016, ctx);

    expect(dragon.mouthWorldPosition).toHaveBeenCalledTimes(1);
    const [flame] = events.payloads('player:flame');
    expect(flame.origin.x).toBeCloseTo(4, 10);
    expect(flame.origin.y).toBeCloseTo(5, 10);
    expect(flame.origin.z).toBeCloseTo(6, 10);
  });

  test('the flame expires and the player returns to the ground state', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player, events } = makeHarness({
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0, 0], state: 'flame', grounded: true });
    controller.flameTime = 0.05;

    controller.update(0.1, ctx);

    expect(controller.flameTime).toBeLessThanOrEqual(0);
    expect(player.state).toBe('ground');
    expect(events.payloads('player:flame')).toEqual([{ on: false }]);
  });

  test('cannot start a flame while hurt', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ pressed: { flame: true } }),
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0, 0], state: 'hurt', grounded: true });
    controller.hurtTime = 0.4;

    controller.update(0.016, ctx);

    expect(controller.flameTime).toBe(0);
    expect(events.names()).not.toContain('player:flame');
  });

  test('cannot start a flame while gliding', () => {
    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ pressed: { flame: true } }),
    });
    pose(player, { state: 'glide', grounded: false });
    controller._hoverUsed = true;

    controller.update(0.016, ctx);

    expect(controller.flameTime).toBe(0);
    expect(events.names()).not.toContain('player:flame');
    expect(player.state).toBe('glide');
  });
});

