describe('Controller.update — horizontal movement', () => {
  test('accelerates up to run speed along the camera-relative stick direction', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player } = makeHarness({
      input: makeInput({ move: [0, 1] }),
      world: makeWorld({ ground }),
      forward: [0, 0, 1],
    });
    pose(player, { position: [0, 0, 0], state: 'ground', grounded: true, yaw: 0 });

    run(controller, ctx, 60, 0.016);

    expect(player.velocity.z).toBeCloseTo(RUN_SPEED, 3);
    expect(player.velocity.x).toBeCloseTo(0, 6);
    expect(player.speed).toBeCloseTo(RUN_SPEED, 3);
    expect(player.grounded).toBe(true);
  });

  test('uses the camera basis rather than world axes for direction', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player } = makeHarness({
      input: makeInput({ move: [1, 0] }),
      world: makeWorld({ ground }),
      forward: [1, 0, 0], // camera looks down +X, so "right" is +Z
    });
    pose(player, { position: [0, 0, 0], state: 'ground', grounded: true, yaw: 0 });

    run(controller, ctx, 60, 0.016);

    expect(player.velocity.z).toBeCloseTo(RUN_SPEED, 3);
    expect(Math.abs(player.velocity.x)).toBeLessThan(0.01);
  });

  test('partial stick deflection yields a proportionally slower run', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player } = makeHarness({
      input: makeInput({ move: [0, 0.5] }),
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0, 0], state: 'ground', grounded: true, yaw: 0 });

    run(controller, ctx, 80, 0.016);

    const expected = RUN_SPEED * (0.35 + 0.65 * 0.5);
    expect(player.speed).toBeCloseTo(expected, 3);
    expect(player.speed).toBeLessThan(RUN_SPEED);
  });

  test('holding charge in the air sprints at sprint speed', () => {
    const { controller, ctx, player } = makeHarness({
      input: makeInput({ move: [0, 1], down: { charge: true } }),
    });
    pose(player, { state: 'air', grounded: false, yaw: 0 });

    run(controller, ctx, 80, 0.016);

    expect(player.state).toBe('air');
    expect(player.speed).toBeCloseTo(SPRINT_SPEED, 2);
    expect(player.speed).toBeGreaterThan(RUN_SPEED);
  });

  test('a standing player with no input coasts to a stop', () => {
    const { controller, ctx, player } = makeHarness();
    pose(player, { state: 'air', grounded: false, velocity: [3, 0, 0] });

    run(controller, ctx, 80, 0.016);

    expect(player.speed).toBeLessThan(0.01);
  });
});

