describe('Controller.update — updrafts', () => {
  const updraft = { x: 0, z: 0, r: 5, topY: 20, baseY: 0, strength: 100 };

  test('lifts an airborne player inside the shaft', () => {
    const { controller, ctx, player } = makeHarness({
      world: makeWorld({ updrafts: [updraft] }),
    });
    pose(player, { position: [0, 5, 0], velocity: [0, 0, 0], state: 'air', grounded: false });

    controller.update(0.1, ctx);

    // gravity alone would leave -2.6; the shaft overcomes it
    expect(player.velocity.y).toBeGreaterThan(0);
    expect(player.velocity.y).toBeCloseTo(5.4, 6);
  });

  test('caps the lift at 17 m/s', () => {
    const { controller, ctx, player } = makeHarness({
      world: makeWorld({ updrafts: [{ ...updraft, strength: 1000 }] }),
    });
    pose(player, { position: [0, 5, 0], velocity: [0, 10, 0], state: 'air', grounded: false });

    controller.update(0.1, ctx);

    expect(player.velocity.y).toBe(17);
  });

  test('a glide gets a stronger lift than an ordinary fall', () => {
    const { controller, ctx, player } = makeHarness({
      world: makeWorld({ updrafts: [updraft] }),
    });
    pose(player, { position: [0, 5, 0], velocity: [0, -3.1, 0], state: 'glide', grounded: false });
    controller._hoverUsed = true;

    controller.update(0.1, ctx);

    expect(player.velocity.y).toBeCloseTo(-3.1 + 100 * 1.25 * 0.1, 6);
  });

  test('ignores shafts the player is outside of', () => {
    const { controller, ctx, player } = makeHarness({
      world: makeWorld({ updrafts: [updraft] }),
    });
    pose(player, { position: [100, 5, 0], velocity: [0, 0, 0], state: 'air', grounded: false });

    controller.update(0.1, ctx);

    expect(player.velocity.y).toBeCloseTo(GRAVITY * 0.1, 10);
  });

  test('ignores shafts the player has risen above', () => {
    const { controller, ctx, player } = makeHarness({
      world: makeWorld({ updrafts: [updraft] }),
    });
    pose(player, { position: [0, 25, 0], velocity: [0, 0, 0], state: 'air', grounded: false });

    controller.update(0.1, ctx);

    expect(player.velocity.y).toBeCloseTo(GRAVITY * 0.1, 10);
  });
});

