describe('Controller.update — ground contact', () => {
  test('lands, snaps to the surface and reports the impact', () => {
    const ground = makeGround({ y: 0, islandId: 7, biome: 'meadow' });
    const { controller, ctx, player, events } = makeHarness({
      world: makeWorld({ ground }),
    });
    pose(player, { position: [2, 0.2, -1], velocity: [0, 0, 0], state: 'air', grounded: false });

    controller.update(0.1, ctx);

    expect(player.grounded).toBe(true);
    expect(player.position.y).toBe(0);
    expect(player.velocity.y).toBe(0);
    expect(player.state).toBe('ground');
    expect(player.islandId).toBe(7);
    expect(player.biome).toBe('meadow');
    expect(controller.coyote).toBeCloseTo(COYOTE_TIME, 10);
    expect(controller.lastGroundPos.x).toBeCloseTo(player.position.x, 10);
    expect(controller.lastGroundPos.y).toBeCloseTo(0, 10);
    expect(controller.lastGroundPos.z).toBeCloseTo(player.position.z, 10);

    const [land] = events.payloads('player:land');
    expect(land.speed).toBeCloseTo(2.6, 10);
    expect(land.biome).toBe('meadow');
    expect(events.payloads('player:enterIsland')).toEqual([
      { island: ground.island, biome: 'meadow' },
    ]);
  });

  test('does not re-announce the island when the biome is unchanged', () => {
    const ground = makeGround({ y: 0, biome: 'meadow' });
    const { controller, ctx, player, events } = makeHarness({
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0.2, 0], state: 'air', grounded: false });
    player.biome = 'meadow';

    controller.update(0.1, ctx);

    expect(events.names()).not.toContain('player:enterIsland');
    expect(events.names()).toContain('player:land');
  });

  test('does not snap to the ground while moving upwards', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player, events } = makeHarness({
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0.03, 0], velocity: [0, 5, 0], state: 'air', grounded: false });

    controller.update(0.1, ctx);

    expect(player.grounded).toBe(false);
    expect(player.state).toBe('air');
    expect(events.names()).not.toContain('player:land');
  });

  test('does not re-announce landing on every grounded frame', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player, events } = makeHarness({
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0, 0], state: 'ground', grounded: true });
    player.biome = 'meadow';

    run(controller, ctx, 10, 0.016);

    expect(events.names()).not.toContain('player:land');
    expect(player.grounded).toBe(true);
    expect(player.state).toBe('ground');
    expect(player.position.y).toBe(0);
  });

  test('stays airborne when there is no ground under the player', () => {
    const { controller, ctx, player } = makeHarness({ world: makeWorld({ ground: null }) });
    pose(player, { position: [0, 3, 0], state: 'ground', grounded: true });

    controller.update(0.1, ctx);

    expect(player.grounded).toBe(false);
    expect(player.state).toBe('air');
  });

  test('landing out of a glide cancels the glide and resets the jump chain', () => {
    const ground = makeGround({ y: 0 });
    const { controller, ctx, player, events } = makeHarness({
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0.1, 0], velocity: [0, -3, 0], state: 'glide', grounded: false });
    controller.jumpCount = 2;
    controller._hoverUsed = true;

    controller.update(0.1, ctx);

    expect(player.state).toBe('ground');
    expect(player.grounded).toBe(true);
    expect(controller.jumpCount).toBe(0);
    expect(controller._hoverUsed).toBe(false);
    expect(events.payloads('player:glide')).toEqual([{ on: false }]);
    expect(events.names()).toContain('player:land');
  });

  test('slides off ground that is too steep', () => {
    const normal = new THREE.Vector3(0.5, 0.5, 0);
    const ground = makeGround({ y: 0, slope: 1.0, normal });
    const { controller, ctx, player } = makeHarness({
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0.1, 0], velocity: [0, 0, 0], state: 'air', grounded: false });

    controller.update(0.1, ctx);

    expect(player.grounded).toBe(false);
    expect(player.state).toBe('air');
    expect(player.velocity.x).toBeGreaterThan(0);
  });

  test('keeps the player on ground that is within the slope limit', () => {
    const normal = new THREE.Vector3(0.5, 0.5, 0).normalize();
    const ground = makeGround({ y: 0, slope: 0.4, normal });
    const { ctx, player, controller } = makeHarness({
      world: makeWorld({ ground }),
    });
    pose(player, { position: [0, 0.1, 0], velocity: [0, 0, 0], state: 'air', grounded: false });

    controller.update(0.1, ctx);

    expect(player.grounded).toBe(true);
    expect(player.state).toBe('ground');
    expect(player.groundNormal.x).toBeCloseTo(normal.x, 10);
  });
});

describe('Controller.update — obstacle collision', () => {
  test('pushes the player out of a blocking cylinder', () => {
    const blocker = { x: 0.2, y: 0, z: 0, r: 1, h: 2 };
    const { controller, ctx, player } = makeHarness({
      world: makeWorld({ blockers: [blocker] }),
    });
    pose(player, { position: [0, 0, 0], velocity: [0, 0, 0], state: 'air', grounded: false });

    controller.update(0.1, ctx);

    const distance = Math.hypot(player.position.x - blocker.x, player.position.z - blocker.z);
    expect(distance).toBeCloseTo(blocker.r + PLAYER_RADIUS, 6);
  });

  test('ignores blockers the player is passing over or under', () => {
    const blocker = { x: 0, y: 10, z: 0, r: 1, h: 2 };
    const { controller, ctx, player } = makeHarness({
      world: makeWorld({ blockers: [blocker] }),
    });
    pose(player, { position: [0, 0, 0], velocity: [0, 0, 0], state: 'air', grounded: false });

    controller.update(0.1, ctx);

    expect(player.position.x).toBeCloseTo(0, 10);
    expect(player.position.z).toBeCloseTo(0, 10);
  });

  test('charging into a blocker bounces the player off and ends the charge', () => {
    const blocker = { x: 0.3, y: 0, z: 0, r: 1, h: 2 };
    const fx = { screenShake: jest.fn() };
    const { controller, ctx, player, events } = makeHarness({
      input: makeInput({ down: { charge: true } }),
      world: makeWorld({ blockers: [blocker] }),
      fx,
    });
    pose(player, { position: [0, 0, 0], velocity: [0, 0, 0], state: 'charge', grounded: true, yaw: Math.PI / 2 });
    controller.chargeTime = 0.2;

    controller.update(0.1, ctx);

    expect(events.payloads('player:charge')).toEqual([{ on: false }]);
    expect(player.state).toBe('air');
    expect(player.velocity.y).toBeGreaterThanOrEqual(4);
    expect(fx.screenShake).toHaveBeenCalled();
    const distance = Math.hypot(player.position.x - blocker.x, player.position.z - blocker.z);
    expect(distance).toBeGreaterThan(blocker.r + PLAYER_RADIUS - 0.01);
  });
});

