describe('Controller.update — falling out of the world', () => {
  test('falling below the kill plane damages the player and respawns them', () => {
    const { controller, ctx, player, events } = makeHarness({ killPlaneY: -50 });
    pose(player, { position: [0, -60, 0], velocity: [0, 0, 0], state: 'air', grounded: false });
