function buildLevelGraph(rng, opts = {}) {
  const difficulty = opts.difficulty ?? 1;
  const pathLength = opts.pathLength ?? rng.int(5, 7);
  const branchCount = opts.branchCount ?? rng.int(2, 3);
  const totalIslands = pathLength + branchCount;
  const biomes = pickBiomeSequence(rng, totalIslands);

  const islands = [];
  const links = [];

  // --- critical path: a meandering chain the player follows to the portal ---
  let heading = rng.range(0, Math.PI * 2);
  let cursor = new THREE.Vector2(0, 0);
  let prevRadius = 0;
  let baseY = 0;

  for (let i = 0; i < pathLength; i++) {
    const isFirst = i === 0;
    const isLast = i === pathLength - 1;

    // Radii swing so the level has rhythm: wide arenas next to tight approaches.
    const radius = isFirst
      ? rng.range(52, 62)
      : isLast
        ? rng.range(58, 70)
        : rng.range(38, 74);

    if (!isFirst) {
      // Turn, but never so hard that the chain folds back onto itself.
      heading += rng.gauss(0, 0.62);
      const gap = rng.range(20, 42);
      const dist = prevRadius + radius + gap;
      cursor = cursor.clone().add(new THREE.Vector2(Math.cos(heading), Math.sin(heading)).multiplyScalar(dist));
      // Height drifts upward overall so the realm climbs toward the portal.
      baseY += rng.gauss(6, 13) + 2;
      baseY = clamp(baseY, -22, 78);
    }

    islands.push({
      id: islands.length,
      center: new THREE.Vector3(cursor.x, baseY, cursor.y),
      radius,
      biome: biomes[islands.length],
      role: isFirst ? 'spawn' : isLast ? 'portal' : 'path',
      pathIndex: i,
      plateaus: [],
      hazard: !isFirst && rng.bool(0.25 + difficulty * 0.08),
    });
    prevRadius = radius;
  }

  // --- branches: optional islands hanging off the path, for collectibles ---
  const branchHosts = rng.shuffle(islands.filter((n) => n.role === 'path').map((n) => n.id));
  for (let b = 0; b < branchCount; b++) {
    const hostId = branchHosts[b % Math.max(1, branchHosts.length)];
    const host = islands[hostId] ?? islands[0];
    const radius = rng.range(26, 40);
    // Push off the host perpendicular-ish to the path so branches read as detours.
    let placed = null;
    for (let attempt = 0; attempt < 24; attempt++) {
      const a = rng.range(0, Math.PI * 2);
      const gap = rng.range(18, 34);
      const dist = host.radius + radius + gap;
      const p = new THREE.Vector3(
        host.center.x + Math.cos(a) * dist,
        host.center.y + rng.gauss(4, 11),
        host.center.z + Math.sin(a) * dist
      );
      if (!overlapsAny(islands, p, radius, 14)) {
        placed = p;
        break;
      }
    }
    if (!placed) continue;

    const node = {
      id: islands.length,
      center: placed,
      radius,
      biome: biomes[islands.length % biomes.length],
      role: 'branch',
      pathIndex: host.pathIndex,
      plateaus: [],
      hazard: rng.bool(0.3),
      hostId: host.id,
    };
    islands.push(node);
    links.push(makeLink(rng, host, node, true));
  }

  // --- links along the critical path ---
  for (let i = 1; i < pathLength; i++) {
    links.push(makeLink(rng, islands[i - 1], islands[i], false));
  }

  // --- plateaus: flat pads the terrain pass must honour ---
  for (const isl of islands) {
    // Every island gets a landing pad at each of its link endpoints so the
    // player never arrives on a slope they slide off.
    for (const link of links) {
      if (link.a === isl.id) isl.plateaus.push({ x: link.from.x, z: link.from.z, r: 7, strength: 1 });
      if (link.b === isl.id) isl.plateaus.push({ x: link.to.x, z: link.to.z, r: 7, strength: 1 });
    }
  }

  // --- mission sites ---
  const eggSites = [];
  const eggIslands = islands.filter((n) => n.role !== 'spawn');
  const eggCount = clamp(Math.round(eggIslands.length * 0.85), 3, 8);
  const eggHosts = rng.shuffle(eggIslands.slice()).slice(0, eggCount);
  for (const isl of eggHosts) {
    const [dx, dz] = rng.disc(isl.radius * 0.62);
    const pos = new THREE.Vector3(isl.center.x + dx, 0, isl.center.z + dz);
    isl.plateaus.push({ x: pos.x, z: pos.z, r: 9, strength: 0.85 });
    eggSites.push({
      island: isl.id,
      pos,
      guarded: rng.bool(0.55 + difficulty * 0.1),
      // Locked eggs need their island's gate enemies cleared first.
      locked: isl.role === 'branch' ? false : rng.bool(0.3),
    });
  }

  // --- enemy encounter sites ---
  const enemySites = [];
  for (const isl of islands) {
    if (isl.role === 'spawn') {
      // The opening island gets one soft encounter, far from the spawn point.
      const a = rng.range(0, Math.PI * 2);
      const d = isl.radius * 0.65;
      enemySites.push({
        island: isl.id,
        pos: new THREE.Vector3(isl.center.x + Math.cos(a) * d, 0, isl.center.z + Math.sin(a) * d),
        count: 1,
        kind: 'patrol',
      });
      continue;
    }
    const groups = rng.int(2, 3 + Math.floor(difficulty));
    for (let g = 0; g < groups; g++) {
      const [dx, dz] = rng.disc(isl.radius * 0.78);
      enemySites.push({
        island: isl.id,
        pos: new THREE.Vector3(isl.center.x + dx, 0, isl.center.z + dz),
        count: rng.int(1, 3),
        kind: rng.weighted(
          [{ k: 'patrol' }, { k: 'guard' }, { k: 'ambush' }, { k: 'nest' }],
          [4, 3, 2, 1]
        ).k,
      });
    }
  }

  // Gate encounters guard each locked egg.
  for (const egg of eggSites) {
    if (!egg.locked) continue;
    egg.gateId = enemySites.length;
    enemySites.push({
      island: egg.island,
      pos: egg.pos.clone().add(new THREE.Vector3(rng.gauss(0, 6), 0, rng.gauss(0, 6))),
      count: rng.int(2, 3),
      kind: 'gate',
      guardsEgg: eggSites.indexOf(egg),
    });
  }

  // --- spawn + portal ---
  const spawnIsland = islands[0];
  const spawn = new THREE.Vector3(spawnIsland.center.x, 0, spawnIsland.center.z);
  spawnIsland.plateaus.push({ x: spawn.x, z: spawn.z, r: 12, strength: 1 });

  const portalIsland = islands.find((n) => n.role === 'portal');
  const portalPos = new THREE.Vector3(
    portalIsland.center.x + rng.gauss(0, portalIsland.radius * 0.2),
    0,
    portalIsland.center.z + rng.gauss(0, portalIsland.radius * 0.2)
  );
  portalIsland.plateaus.push({ x: portalPos.x, z: portalPos.z, r: 13, strength: 1 });

  // --- world bounds, used to size sky/water and the fall-out plane ---
  const bounds = new THREE.Box3();
  for (const isl of islands) {
    bounds.expandByPoint(
      new THREE.Vector3(isl.center.x - isl.radius, isl.center.y - 60, isl.center.z - isl.radius)
    );
    bounds.expandByPoint(
      new THREE.Vector3(isl.center.x + isl.radius, isl.center.y + 60, isl.center.z + isl.radius)
    );
  }

  let minY = Infinity;
  for (const isl of islands) minY = Math.min(minY, isl.center.y);

  return {
    seed: rng.seed,
    difficulty,
    islands,
    links,
    eggSites,
    enemySites,
    spawn,
    portal: { island: portalIsland.id, pos: portalPos },
    eggTotal: eggSites.length,
    bounds,
    killPlaneY: minY - 95,
    name: makeRealmName(rng),
  };
}

