  test('places branches as linked detours on critical-path hosts', () => {
    const graph = build(12345, { difficulty: 1, pathLength: 5, branchCount: 2 });

    const branches = graph.islands.filter((island) => island.role === 'branch');
    expect(branches).toHaveLength(2);
    expect(graph.islands).toHaveLength(7);
    expect(graph.links).toHaveLength(6);

    for (const branch of branches) {
      const host = graph.islands[branch.hostId];
      expect(host).toBeDefined();
      expect(host.role).toBe('path');
      expect(branch.pathIndex).toBe(host.pathIndex);
      expect(branch.radius).toBeGreaterThanOrEqual(26);
      expect(branch.radius).toBeLessThan(40);
      expect(distance2D(branch.center, host.center)).toBeGreaterThan(host.radius + branch.radius);
      expect(BIOME_IDS.has(branch.biome)).toBe(true);

      const branchLink = graph.links.find(
        (link) => link.a === host.id && link.b === branch.id
      );
      expect(branchLink).toBeDefined();
      expect(branchLink.from).toBeInstanceOf(THREE.Vector3);
      expect(branchLink.to).toBeInstanceOf(THREE.Vector3);
      expect(plateauAt(host.plateaus, branchLink.from, 7, 1)).toBe(true);
      expect(plateauAt(branch.plateaus, branchLink.to, 7, 1)).toBe(true);
    }

    const branchLinkCount = graph.links.filter((link) =>
      branches.some((branch) => branch.id === link.b)
    ).length;
    expect(branchLinkCount).toBe(branches.length);
    expect(graph.links.length - branchLinkCount).toBe(4);

    const chain = chainIslands(graph);
    for (let index = 1; index < chain.length; index++) {
      expect(
        graph.links.some(
          (link) => link.a === chain[index - 1].id && link.b === chain[index].id
        )
      ).toBe(true);
    }
  });

  test('falls back to the spawn island as a branch host when there are no path-role islands', () => {
    const graph = build(7, { difficulty: 0, pathLength: 2, branchCount: 1 });

    expect(graph.difficulty).toBe(0);
    expect(chainIslands(graph).map((island) => island.role)).toEqual(['spawn', 'portal']);

    const branch = graph.islands.find((island) => island.role === 'branch');
    expect(branch).toBeDefined();
    expect(branch.hostId).toBe(0);
    expect(branch.pathIndex).toBe(0);
    expect(graph.links.some((link) => link.a === 0 && link.b === branch.id)).toBe(true);

    // There are only two eligible egg islands, so the intended minimum of three
    // cannot be reached; every eligible island still receives exactly one egg.
    expect(graph.eggTotal).toBe(2);
    expect(new Set(graph.eggSites.map((egg) => egg.island))).toEqual(new Set([1, 2]));
  });

  test('creates consistent egg, enemy, and gate mission sites', () => {
    const difficulty = 1;
    const graph = build(42, { difficulty, pathLength: 6, branchCount: 0 });
    const nonSpawnCount = graph.islands.length - 1;
    const expectedEggCount = Math.min(
      nonSpawnCount,
      clamp(Math.round(nonSpawnCount * 0.85), 3, 8)
    );

    expect(graph.eggTotal).toBe(graph.eggSites.length);
    expect(graph.eggSites).toHaveLength(expectedEggCount);
    expect(new Set(graph.eggSites.map((egg) => egg.island)).size).toBe(
      graph.eggSites.length
    );

    for (const egg of graph.eggSites) {
      const host = graph.islands[egg.island];
      expect(host.role).not.toBe('spawn');
      expect(egg.pos).toBeInstanceOf(THREE.Vector3);
      expect(egg.pos.y).toBe(0);
      expect(distance2D(egg.pos, host.center)).toBeLessThanOrEqual(host.radius * 0.62);
      expect(typeof egg.guarded).toBe('boolean');
      expect(typeof egg.locked).toBe('boolean');
      expect(egg.locked && host.role === 'branch').toBe(false);
      expect(plateauAt(host.plateaus, egg.pos, 9, 0.85)).toBe(true);
    }

    const spawnSites = graph.enemySites.filter((site) => site.island === 0);
    expect(spawnSites).toHaveLength(1);
    expect(spawnSites[0]).toEqual(expect.objectContaining({ count: 1, kind: 'patrol' }));
    expect(spawnSites[0].pos.y).toBe(0);
    expect(distance2D(spawnSites[0].pos, graph.islands[0].center)).toBeLessThanOrEqual(
      graph.islands[0].radius * 0.65
    );

    const maxGroups = 3 + Math.floor(difficulty);
    for (const island of graph.islands.slice(1)) {
      const groups = regularEnemiesOn(graph, island.id);
      expect(groups.length).toBeGreaterThanOrEqual(2);
      expect(groups.length).toBeLessThanOrEqual(maxGroups);
      for (const enemy of groups) {
        expect(REGULAR_ENEMY_KINDS.has(enemy.kind)).toBe(true);
        expect(enemy.count).toBeGreaterThanOrEqual(1);
        expect(enemy.count).toBeLessThanOrEqual(3);
        expect(enemy.pos.y).toBe(0);
        expect(distance2D(enemy.pos, island.center)).toBeLessThanOrEqual(island.radius * 0.78);
      }
    }

    const lockedEggs = graph.eggSites.filter((egg) => egg.locked);
    const gateSites = graph.enemySites.filter((site) => site.kind === 'gate');
    expect(gateSites).toHaveLength(lockedEggs.length);

    for (const [eggIndex, egg] of graph.eggSites.entries()) {
      if (!egg.locked) {
        expect(egg.gateId).toBeUndefined();
        continue;
      }
      expect(egg.gateId).toEqual(expect.any(Number));
      const gate = graph.enemySites[egg.gateId];
      expect(gate).toBeDefined();
      expect(gate.kind).toBe('gate');
      expect(gate.island).toBe(egg.island);
      expect(gate.guardsEgg).toBe(eggIndex);
      expect(gate.count).toBeGreaterThanOrEqual(2);
      expect(gate.count).toBeLessThanOrEqual(3);
      expect(gate.pos.y).toBe(0);
    }
  });

  test('honours higher difficulty and caps mission sites for large levels', () => {
    const graph = build(8, { difficulty: 3, pathLength: 10, branchCount: 4 });
    const branchIslands = graph.islands.filter((island) => island.role === 'branch');
    const nonSpawnCount = graph.islands.length - 1;
    const expectedEggCount = Math.min(
      nonSpawnCount,
      clamp(Math.round(nonSpawnCount * 0.85), 3, 8)
    );

    expect(graph.difficulty).toBe(3);
    expect(branchIslands).toHaveLength(4);
    expect(graph.islands).toHaveLength(14);
    expect(graph.eggTotal).toBe(expectedEggCount);
    expect(graph.eggTotal).toBe(8);

    for (const island of graph.islands.slice(1)) {
      const groups = regularEnemiesOn(graph, island.id);
      expect(groups.length).toBeGreaterThanOrEqual(2);
      expect(groups.length).toBeLessThanOrEqual(6);
    }

    for (const branch of branchIslands) {
      expect(branch.pathIndex).toBe(graph.islands[branch.hostId].pathIndex);
    }
  });

  test('derives the world bounds and kill plane from island extents', () => {
    const graph = build(12345, { difficulty: 1, pathLength: 5, branchCount: 2 });

    let minX = Infinity;
    let minY = Infinity;
    let minZ = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    let maxZ = -Infinity;

    for (const island of graph.islands) {
      minX = Math.min(minX, island.center.x - island.radius);
      minY = Math.min(minY, island.center.y - 60);
      minZ = Math.min(minZ, island.center.z - island.radius);
      maxX = Math.max(maxX, island.center.x + island.radius);
      maxY = Math.max(maxY, island.center.y + 60);
      maxZ = Math.max(maxZ, island.center.z + island.radius);
    }

    expect(graph.bounds).toBeInstanceOf(THREE.Box3);
    expect(graph.bounds.min.toArray()).toEqual([minX, minY, minZ]);
    expect(graph.bounds.max.toArray()).toEqual([maxX, maxY, maxZ]);
    expect(graph.bounds.isEmpty()).toBe(false);
    expect(graph.killPlaneY).toBe(Math.min(...graph.islands.map((island) => island.center.y)) - 95);
  });

  test.each([0, 1, -1])(
    'throws when pathLength=%s cannot provide both a spawn and a portal',
    (pathLength) => {
      expect(() => build(1, { pathLength, branchCount: 0 })).toThrow(TypeError);
    }
  );
});
